insert into ponew values
(1, 1, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'The three elements of the fire triangle in theatre are:', '["Diathermy, laser and suction tubing", "Heat, light and electricity from lamps", "Oxygen, nitrous oxide and the warming blanket on the table", "An ignition source, a fuel and an oxidiser"]'::jsonb, 3, 'Diathermy/laser (ignition), drapes/alcohol (fuel), oxygen/nitrous oxide (oxidiser).', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 2, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'The tourniquet inflation time must be recorded and the surgeon told:', '["Never, as it is the anaesthetist''s job", "Only if the patient complains of pain", "Only when the operation ends and the tourniquet has been fully released", "At regular intervals, e.g. each hour of inflation"]'::jsonb, 3, 'Prolonged ischaemia damages nerves and muscle.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 3, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'The maximum safe dose of plain lidocaine (without adrenaline) for infiltration is about:', '["0.3 mg/kg, even with adrenaline added", "30 mg/kg, as there is no real maximum", "15 mg/kg (about 1 g in an adult)", "3 mg/kg (about 200 mg in an adult)"]'::jsonb, 3, 'With adrenaline it is about 7 mg/kg (up to 500 mg).', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 4, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Double gloving during surgery is recommended mainly because it:', '["It makes fine instrument handling much easier", "It allows the scrub nurse to skip the surgical hand scrub before the case", "It removes the need for a surgical hand scrub", "It reduces blood exposure if the outer glove is punctured"]'::jsonb, 3, 'Perforation indicator systems show a coloured inner glove through a puncture.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 5, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Between cases, the operating room should have:', '["Full terminal cleaning of the walls and the ceiling", "Cleaning of patient-contact surfaces, equipment and nearby floor", "No cleaning at all if the previous case was clean, so the list can run on time", "Emptying of the bins only, as the room is still in use"]'::jsonb, 1, 'Terminal cleaning is done at the end of the day.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 6, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Which suture is absorbable?', '["Polypropylene (Prolene), a monofilament", "Nylon (Ethilon)", "Polyglactin 910 (Vicryl)", "Polypropylene (Prolene)"]'::jsonb, 2, 'Vicryl is absorbed in about 60–90 days; nylon and Prolene are permanent.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 7, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Hand hygiene before putting on sterile gloves for minor procedures can be done with:', '["Nothing at all, as the gloves themselves are sterile", "Plain tap water only, as gloves will cover the hands", "An alcohol-based surgical hand rub, if the hands are visibly clean", "A dry paper towel only, wiping each finger and the palm in turn for a minute"]'::jsonb, 2, 'Wash with soap and water first if the hands are soiled.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 8, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Under anaesthesia, the anaesthetist controls the head during transfer mainly to:', '["Protect the airway and cervical spine", "Check the patient''s identity band against the list again", "Keep the patient''s eyes closed", "Count the transfer staff aloud"]'::jsonb, 0, 'The team moves on the anaesthetist''s command.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 9, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'An instrument tray arrives with a missing instrument from the tray list. The nurse should:', '["Borrow one from another open tray nearby", "Change the tray list so that it matches what is in the tray", "Record and report it, and get a replacement", "Ignore it if the operation is a short one"]'::jsonb, 2, 'Accurate tray lists make counts reliable.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 10, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Pre-operative skin washing with chlorhexidine the night before and morning of surgery aims to:', '["Remove all body hair from the operative area so that shaving is not needed", "Reduce skin bacterial load and surgical site infection", "Make the skin easier for the surgeon to mark", "Sterilise the skin completely before incision"]'::jsonb, 1, 'Skin can never be made sterile, only cleaner.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 11, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'An alternate-site diathermy burn is most likely when:', '["The return plate is on a well-perfused thigh", "Part of the patient''s skin touches metal on the table", "The patient''s skin is completely dry and insulated", "Bipolar diathermy is used with the forceps tips close together"]'::jsonb, 1, 'Current takes the path of least resistance.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 12, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'The circulating nurse can safely hand items to the scrub nurse by:', '["Opening the packs directly over the open wound", "Reaching across the sterile field to place them", "Presenting them so the scrub nurse can take them safely", "Throwing them gently onto the instrument table from a safe distance away"]'::jsonb, 2, 'Keep a safe distance from the sterile field.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 13, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'All medicine containers and syringes on the sterile field should be:', '["Left unlabelled to save time, as long as the scrub nurse remembers each one", "Labelled only at the end of the case for records", "Labelled only if more than three drugs are used", "Labelled with drug and strength, even if only one is used"]'::jsonb, 3, 'Unlabelled syringes cause wrong-drug errors.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 14, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'If an airway fire occurs during surgery, the first actions are to:', '["Increase the oxygen to 100%, keep the tube in and continue the operation", "Leave the tube in place and wait for senior help", "Increase oxygen to 100% and continue with surgery", "Stop gas flow, remove the tube and pour saline into the airway"]'::jsonb, 3, 'Then ventilate with air, re-intubate and assess the airway.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 15, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'The best description of healing by primary intention is:', '["The wound is closed after several days of being left open", "The wound is left open to fill with granulation tissue", "Wound edges are brought together, healing quickly with minimal scar", "The wound is left open and heals slowly from the base by granulation tissue"]'::jsonb, 2, 'Secondary intention is used for infected wounds; tertiary is delayed primary closure.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 16, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Patient identity in theatre is confirmed by:', '["Asking the porter who brought the patient who the patient is", "Calling out the patient''s name and waiting for a nod in reply", "Reading the name on the operating list and the trolley label, without asking", "Asking the patient''s name and date of birth and checking the band"]'::jsonb, 3, 'Use at least two identifiers at every handover.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 17, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Theatre doors should be kept closed during surgery mainly to:', '["Maintain positive pressure and limit airborne contamination", "Stop the anaesthetic gases from reaching the corridor", "Keep the noise of surgery inside so patients outside are not disturbed", "Prevent the surgeon from being distracted by visitors"]'::jsonb, 0, 'Each door opening disturbs airflow and raises bacterial counts.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 18, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'A safety strap for a supine patient on the operating table is placed:', '["Directly over the abdomen, at the waist", "Over both ankles, fastened firmly so that the legs cannot move at all", "Tightly across the chest, under the arms", "About 5 cm above the knees, loosely over a blanket"]'::jsonb, 3, 'It must not restrict circulation or breathing.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 19, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'A sudden fall in end-tidal CO₂ with hypotension during laparoscopic insufflation suggests:', '["Normal absorption of CO₂", "Light anaesthesia", "Gas embolism", "Hypoglycaemia"]'::jsonb, 2, 'Stop insufflation, release the pneumoperitoneum and support circulation.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 20, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Specimens for microbiological culture should be sent:', '["Fixed straight away in 10% formalin, like a routine histology specimen", "Frozen at −20 °C for one week", "Fresh in a sterile container without formalin", "Mixed with chlorhexidine first"]'::jsonb, 2, 'Formalin kills the organisms that need to be grown.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 21, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Wound closure with skin staples is removed usually:', '["Never, as they dissolve away", "After 7–14 days, depending on site", "Within 24 hours of surgery", "Within 24–48 hours for all wounds, to reduce the risk of infection"]'::jsonb, 1, 'Facial sutures come out earlier (about 3–5 days).', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 22, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'A small fire starts on the drapes. The immediate action is to:', '["Keep operating while someone calls the fire service", "Keep operating while someone goes to call the fire service from outside", "Remove the burning drapes from the patient and extinguish them", "Increase the oxygen flow to the patient''s face mask"]'::jsonb, 2, 'Use water/saline or a CO₂ extinguisher as appropriate.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 23, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'A patient with an implantable cardioverter-defibrillator (ICD) needs monopolar diathermy. The team should:', '["Avoid ECG monitoring during surgery to reduce interference", "Have the ICD switched off, with an external defibrillator ready", "Place the diathermy return plate directly over the ICD to protect it from current", "Place the diathermy return plate directly over the ICD site"]'::jsonb, 1, 'Diathermy can trigger inappropriate shocks; reactivate the ICD after surgery.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 24, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'A diathermy pencil not in use should be kept:', '["In the scrub nurse''s hand at all times", "In an insulated holster, not on the drapes", "On the patient''s chest, ready for use", "In a bowl of saline on the instrument trolley, to keep the tip clean and cool"]'::jsonb, 1, 'An activated pencil on drapes can burn the patient or start a fire.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 25, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Consent for surgery in an unconscious adult needing emergency life-saving surgery:', '["Must be signed by the most senior nurse on duty before surgery can begin", "Must wait until the patient wakes up and can sign", "Is not needed; treat in the patient''s best interests", "Requires a court order every time, even in emergency"]'::jsonb, 2, 'Document the reasons; inform relatives where possible.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 26, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'The scrub nurse''s main responsibility before the operation starts is to:', '["Obtain the patient''s written consent for surgery", "Set up the sterile field and instruments and do the first count", "Give the premedication on the ward beforehand", "Transfer the patient onto the operating table and apply the safety strap"]'::jsonb, 1, 'The circulating nurse records counts and fetches supplies.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 27, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'A Deaver retractor is used mainly in:', '["Deep abdominal surgery to hold back organs", "Eye surgery, to hold the eyelid open", "Dental extraction, to hold the cheek", "Hand surgery, to hold back the skin edges of small wounds"]'::jsonb, 0, 'Self-retaining retractors (e.g. Balfour) free the assistant''s hands.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 28, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Abdominal swabs are counted and bagged in:', '["Fives, counted aloud by two nurses together", "Tens, counted silently by the surgeon at the end of the operation", "Random groups, counted at the very end", "Any number, counted by one person alone"]'::jsonb, 0, 'Two people count visibly and audibly, using a standard system.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 29, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Enhanced recovery (ERAS) recommends that most patients should be given:', '["Clear carbohydrate drinks up to 2 hours before anaesthesia", "A heavy meal up to 1 hour before going to theatre, to give energy for surgery", "Full bowel preparation before every single operation", "Nothing by mouth from the morning of the day before"]'::jsonb, 0, 'It reduces insulin resistance and patient discomfort.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 30, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'The perioperative nurse acting as patient advocate during anaesthesia ensures that:', '["Documentation is skipped to save valuable time", "The surgeon''s preferences always come first, as the patient cannot speak", "The patient''s dignity, privacy and safety are protected", "Visitors are allowed in to watch the procedure"]'::jsonb, 2, 'The anaesthetised patient cannot speak for themselves.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 31, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'A conventionally ventilated operating room should have about how many air changes per hour?', '["About 5–6", "About 2–3", "About 1, as more air movement spreads bacteria", "At least 20"]'::jsonb, 3, 'Frequent filtered air changes dilute airborne bacteria shed by staff.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 32, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', '''Event-related sterility'' means that a sterile pack stays sterile until:', '["A fixed expiry date of exactly 7 days after sterilisation", "It has been moved even once from the store to the theatre", "It reaches a fixed expiry date of exactly 7 days after the sterilisation cycle", "Something damages it, such as a tear, moisture or broken seal"]'::jsonb, 3, 'Check packs for damage, moisture and indicator change before opening.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 33, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Scrubbed staff should keep their hands:', '["Between chest and waist level, in front of the body", "Tucked into the axillae to keep them warm and away from the sterile field", "Below the waist, so the arms can relax", "Behind the back, away from the field"]'::jsonb, 0, 'Anything below the waist or out of sight is considered unsterile.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 34, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Chemical indicator tape on the outside of a pack shows that:', '["The pack was exposed to the sterilising process", "The contents inside are definitely sterile", "The pack has passed its daily Bowie–Dick test", "All the spores placed inside the pack have definitely been killed"]'::jsonb, 0, 'Internal indicators and biological indicators give more information.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 35, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Pooling of skin preparation solution under the patient can cause:', '["Improved antisepsis of the back", "Chemical burns and diathermy-related fires", "Better adhesion of the diathermy plate", "Faster wound healing because more antiseptic stays on the skin"]'::jsonb, 1, 'Check that drapes and sheets are dry and remove soaked linen.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 36, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Exsanguination with an Esmarch bandage before tourniquet inflation should be avoided when there is:', '["A clean ligament repair of the knee in a young adult", "Infection or a tumour in the limb", "Normal, healthy limb skin", "A planned knee arthroscopy"]'::jsonb, 1, 'Squeezing could spread infection, tumour cells or emboli.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 37, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Sterile tables should be opened:', '["Close to the start of the case, and never left unattended", "Only after the patient is anaesthetised and draped", "The night before, to save time in the morning", "At least 4 hours before the patient arrives, to save time for the team"]'::jsonb, 0, 'Sterility is event-related; an unwatched field cannot be confirmed sterile.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 38, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Inadvertent perioperative hypothermia is a core temperature below:', '["38 °C", "36 °C", "37.5 °C", "34 °C only"]'::jsonb, 1, 'Hypothermia increases bleeding, infection and cardiac events.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 39, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Theatre traffic is best controlled by:', '["Limiting the number of people and movement during surgery", "Keeping the theatre doors propped wide open", "Allowing students to walk freely in and out so they can see each step", "Encouraging staff to change rooms frequently"]'::jsonb, 0, 'Fewer people means fewer airborne bacteria.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 40, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Dry heat sterilisation (hot air oven) typically requires:', '["60 °C for 30 minutes in hot water", "160 °C for 2 hours (or 170 °C for 1 hour)", "121 °C for 15 minutes using steam", "100 °C for 5 minutes by boiling, which is enough for all instruments"]'::jsonb, 1, 'Dry heat is used for powders, oils and glassware that steam cannot penetrate.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 41, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Residual volume is the amount of air:', '["Inhaled during maximal inspiration beyond tidal volume", "Inhaled during a normal breath", "Remaining in the lungs after maximal expiration", "Exhaled forcefully after normal expiration"]'::jsonb, 2, 'Residual volume is the air that remains in the lungs even after the most forceful expiration, preventing lung collapse.', 'PON 411 · Anatomy & Physiology'),
(1, 42, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Which of the following is NOT a hormone?', '["Atrial natriuretic peptide", "Thymosin", "Renin", "Prolactin"]'::jsonb, 2, 'Renin is an enzyme that converts angiotensinogen to angiotensin I. Prolactin, thymosin and ANP are hormones.', 'PON 411 · Anatomy & Physiology'),
(1, 43, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Stimulation of the sympathetic nervous system typically causes which cardiac effect?', '["Increased heart rate and contractility", "Complete heart block", "Decreased heart rate and contractility", "No cardiac effect"]'::jsonb, 0, 'Sympathetic stimulation releases catecholamines that increase heart rate (chronotropy) and contractility (inotropy) via beta-1 receptors.', 'PON 411 · Anatomy & Physiology'),
(1, 44, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Aldosterone is secreted from which zone of the adrenal cortex?', '["Zona glomerulosa", "Zona fasciculata", "Adrenal medulla", "Zona reticularis"]'::jsonb, 0, 'The zona glomerulosa, the outermost adrenal cortex layer, produces mineralocorticoids such as aldosterone.', 'PON 411 · Anatomy & Physiology'),
(1, 45, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Cranial nerves originate directly from the:', '["Peripheral muscles", "Spinal cord only", "Brain and brainstem", "Autonomic ganglia only"]'::jsonb, 2, 'The 12 pairs of cranial nerves arise directly from the brain and brainstem, unlike spinal nerves which arise from the spinal cord.', 'PON 411 · Anatomy & Physiology'),
(1, 46, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'How many pulmonary veins empty into the right atrium?', '["Four", "None", "One", "Two"]'::jsonb, 1, 'The four pulmonary veins drain oxygenated blood into the LEFT atrium. None enter the right atrium.', 'PON 411 · Anatomy & Physiology'),
(1, 47, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Platelets (thrombocytes) primarily function in:', '["Producing hormones", "Oxygen transport", "Blood clotting/haemostasis", "Fighting bacterial infection"]'::jsonb, 2, 'Platelets are essential for haemostasis, aggregating at sites of vessel injury to help form a clot.', 'PON 411 · Anatomy & Physiology'),
(1, 48, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Hormonal control of a target organ commonly occurs through:', '["Muscle contraction alone", "Hormones binding to specific receptors on or in target cells", "Physical contact between glands and organs", "Direct nerve stimulation only, with no chemical signal"]'::jsonb, 1, 'Hormones exert their effects by binding to specific receptors on or within target cells, triggering a physiological response.', 'PON 411 · Anatomy & Physiology'),
(1, 49, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Total lung capacity is best defined as:', '["The maximum volume of air the lungs can hold after maximal inspiration", "The volume remaining in the lungs after maximal expiration", "The volume of air moved in a single normal breath", "The volume exhaled in the first second of forced expiration"]'::jsonb, 0, 'Total lung capacity is the maximum volume of air the lungs can contain after a maximal inspiratory effort.', 'PON 411 · Anatomy & Physiology'),
(1, 50, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The rhythm of breathing is set by neurons in the:', '["Medulla oblongata", "Pons", "Midbrain", "Hypothalamus"]'::jsonb, 0, 'The basic rhythm of breathing is generated by medullary neurons (pre-Bötzinger complex). The pons modifies it.', 'PON 411 · Anatomy & Physiology'),
(1, 51, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Which muscle aids deep (forced) expiration?', '["Scalenes", "External intercostals", "Rectus abdominis", "Sternocleidomastoid"]'::jsonb, 2, 'Forced (deep) expiration uses the abdominal muscles, such as rectus abdominis, and the internal intercostals. Scalenes, SCM and external intercostals are inspiratory.', 'PON 411 · Anatomy & Physiology'),
(1, 52, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The hepatic portal vein primarily carries blood from the:', '["Liver to the systemic circulation only", "Heart to the liver", "Kidneys to the liver", "Gastrointestinal tract and spleen to the liver"]'::jsonb, 3, 'The hepatic portal vein drains nutrient- and sometimes toxin-rich blood from the GI tract and spleen into the liver for processing before it enters systemic circulation.', 'PON 411 · Anatomy & Physiology'),
(1, 53, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Which gastrointestinal process refers to the physical and chemical breakdown of food into absorbable units?', '["Absorption", "Excretion", "Transportation", "Digestion"]'::jsonb, 3, 'Digestion is the breakdown of food (mechanically and chemically) into smaller, absorbable molecules.', 'PON 411 · Anatomy & Physiology'),
(1, 54, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The bony labyrinth is found in the:', '["Middle ear", "Auricle", "Inner ear", "External auditory canal"]'::jsonb, 2, 'The bony labyrinth (cochlea, vestibule, semicircular canals) lies in the inner ear within the temporal bone.', 'PON 411 · Anatomy & Physiology'),
(1, 55, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The right lung consists of which lobes?', '["Only a posterior lobe", "Upper and lower lobes", "Lower lobe and lingula", "Upper, middle and lower lobes"]'::jsonb, 3, 'The right lung has three lobes (upper, middle, lower). The left has two (upper with lingula, and lower).', 'PON 411 · Anatomy & Physiology'),
(1, 56, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'A glomerulus and glomerular capsule together make up one:', '["Kidney lobule", "Nephron", "Renal capsule", "Renal corpuscle"]'::jsonb, 3, 'The glomerulus and Bowman''s (glomerular) capsule together form the renal corpuscle.', 'PON 411 · Anatomy & Physiology'),
(1, 57, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The short period that occurs during the transmission of impulses through the synapses is:', '["Synaptic simulation", "Synaptic junction", "Synaptic cleft", "Synaptic delay"]'::jsonb, 3, 'Synaptic delay (about 0.5 ms) is the time taken for neurotransmitter release, diffusion and receptor binding at a synapse.', 'PON 411 · Anatomy & Physiology'),
(1, 58, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Absorption of digested nutrients occurs primarily in the:', '["Stomach", "Large intestine", "Oesophagus", "Small intestine"]'::jsonb, 3, 'The small intestine, with its large surface area from villi and microvilli, is the primary site of nutrient absorption.', 'PON 411 · Anatomy & Physiology'),
(1, 59, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Which endocrine gland is most directly involved in immune function?', '["Adrenal glands", "Adenohypophysis", "Thymus", "Pancreas"]'::jsonb, 2, 'The thymus is where T lymphocytes mature (thymosin). It is the endocrine gland most involved in immunity.', 'PON 411 · Anatomy & Physiology'),
(1, 60, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'What is the body''s first metabolic pathway for breaking down glucose to release energy?', '["Glycosides", "Glycolysis", "Glycogenolysis", "Glucosides"]'::jsonb, 1, 'Glycolysis, in the cytoplasm, is the first pathway of glucose breakdown, giving pyruvate and 2 ATP.', 'PON 411 · Anatomy & Physiology'),
(1, 61, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The process by which water and diffusible substances move together across a membrane in response to fluid pressure is:', '["Diffusion", "Osmosis", "Filtration", "Active transport"]'::jsonb, 2, 'Filtration moves water and small solutes together across a membrane under hydrostatic (fluid) pressure, as at the glomerulus.', 'PON 411 · Anatomy & Physiology'),
(1, 62, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The part of the CNS housed within the cranial vault is the:', '["Spinal cord", "Brain", "Medulla oblongata only", "Brainstem only"]'::jsonb, 1, 'The brain lies within the cranial vault. The spinal cord lies in the vertebral canal.', 'PON 411 · Anatomy & Physiology'),
(1, 63, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Which factor does NOT directly affect the rate or depth of respiration?', '["Blood O2 levels", "Blood CO2 levels", "Blood pH", "Blood glucose level"]'::jsonb, 3, 'Respiration is primarily regulated by chemoreceptors sensing CO2, pH and O2 levels — blood glucose has no direct regulatory role in respiratory drive.', 'PON 411 · Anatomy & Physiology'),
(1, 64, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Blood flows from the right atrium to the right ventricle through which valve?', '["Bicuspid (mitral)", "Tricuspid", "Aortic", "Pulmonary"]'::jsonb, 1, 'The right atrioventricular valve is the tricuspid valve. The left is the mitral (bicuspid).', 'PON 411 · Anatomy & Physiology'),
(1, 65, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The urinary bladder''s primary anatomical function is to:', '["Store urine until voiding", "Produce urine", "Reabsorb electrolytes", "Filter blood"]'::jsonb, 0, 'The bladder is a muscular reservoir that stores urine produced by the kidneys until it is voided through the urethra.', 'PON 411 · Anatomy & Physiology'),
(1, 66, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Endocrine glands differ from exocrine glands in that endocrine glands:', '["Always secrete through a duct onto an epithelial surface", "Only function during childhood", "Never produce chemical messengers", "Secrete hormones directly into the bloodstream, with no ducts"]'::jsonb, 3, 'Endocrine glands are ductless — they release hormones directly into the bloodstream, unlike exocrine glands which secrete via ducts.', 'PON 411 · Anatomy & Physiology'),
(1, 67, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'A patient''s arterial blood gas shows low PaO2 despite adequate ventilation. The nurse considers that this could reflect a problem with:', '["The urinary bladder", "The endocrine pancreas", "The heart''s electrical conduction system only", "Gaseous exchange at the alveolar-capillary membrane"]'::jsonb, 3, 'Impaired oxygenation despite adequate ventilation often reflects a gas exchange problem at the alveolar-capillary membrane (e.g. from fluid, inflammation or V/Q mismatch), rather than a ventilation problem itself.', 'PON 411 · Anatomy & Physiology'),
(1, 68, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Water reabsorbed by the collecting duct enters the:', '["Vasa recta", "Nephron loop", "Ureter", "Minor calyx"]'::jsonb, 0, 'Water reabsorbed from the collecting duct passes into the medullary interstitium and is carried away by the vasa recta.', 'PON 411 · Anatomy & Physiology'),
(1, 69, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The portion of the cervix that protrudes into the vagina is covered by:', '["Columnar epithelium", "Transitional epithelium", "Cuboidal epithelium", "Squamous epithelium"]'::jsonb, 3, 'The ectocervix, the part protruding into the vagina, is covered by stratified squamous epithelium. The endocervical canal is lined by columnar epithelium.', 'PON 411 · Anatomy & Physiology'),
(1, 70, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'What proportion of resting cardiac output goes to the brain?', '["5%", "10%", "20%", "15%"]'::jsonb, 3, 'The brain receives about 15% of resting cardiac output (about 750 mL/min).', 'PON 411 · Anatomy & Physiology'),
(1, 71, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'A patient develops a urinary tract infection after an indwelling urinary catheter has been inserted. This would most accurately be termed as which type of infection?', '["An iatrogenic infection", "A chronic infection", "A viral infection", "An opportunistic infection"]'::jsonb, 0, 'An infection caused by a medical device/procedure is termed iatrogenic.', 'GSM 402 · Microbiology & Infection Control'),
(1, 72, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Standard precautions differ from transmission-based precautions in that standard precautions:', '["Replace the need for PPE entirely", "Are only used for confirmed infections", "Apply to ALL patients, all the time", "Are optional depending on staff preference"]'::jsonb, 2, 'Standard precautions form the baseline of care for every patient, regardless of known infection status.', 'GSM 402 · Microbiology & Infection Control'),
(1, 73, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'The most effective way to stop the spread of droplet infections such as influenza is:', '["A surgical mask within 1–2 metres and hand hygiene", "Closing all windows", "An N95 respirator for every visitor, with the windows kept closed", "N95 respirator for all visitors"]'::jsonb, 0, 'Droplets travel short distances.', 'GSM 402 · Microbiology & Infection Control'),
(1, 74, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'An endotoxin is:', '["A protein secreted by Gram-positive bacteria only", "A toxin made only by viruses", "A type of antibiotic", "Part of the cell wall of Gram-negative bacteria"]'::jsonb, 3, 'It triggers septic shock.', 'GSM 402 · Microbiology & Infection Control'),
(1, 75, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Antisepsis specifically refers to:', '["The use of chemical solutions for disinfection", "A synonym for medical asepsis", "Sterilisation of surgical instruments only", "The overall state of being germ-free"]'::jsonb, 0, 'Antisepsis is one specific tool within the broader concept of asepsis — using chemical agents to reduce or kill microorganisms.', 'GSM 402 · Microbiology & Infection Control'),
(1, 76, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Airborne precautions, including use of an N95 respirator, are required for suspected:', '["Pulmonary tuberculosis or measles", "Seasonal influenza", "MRSA wound infection", "Norovirus gastroenteritis"]'::jsonb, 0, 'Airborne precautions with an N95 or higher respirator and negative pressure room are required for pathogens spread via small airborne particles, such as TB and measles.', 'GSM 402 · Microbiology & Infection Control'),
(1, 77, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'The nurse has opened the sterile supplies and put on two sterile gloves to complete a sterile dressing change, a procedure that requires surgical asepsis. The nurse must:', '["Use forceps soaked in a disinfectant.", "Cover the nose and mouth with gloved hands if a sneeze is imminent.", "Keep splashes on the sterile field to a minimum.", "Consider the outer 1 inch of the sterile field as contaminated."]'::jsonb, 3, 'The outer 1 inch of a sterile field is always considered contaminated.', 'GSM 402 · Microbiology & Infection Control'),
(1, 78, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Hepatitis C is mainly transmitted by:', '["Blood-to-blood contact", "Food and water", "Coughing and sneezing near others", "Mosquito bites"]'::jsonb, 0, 'There is no vaccine; needlestick injury is a risk.', 'GSM 402 · Microbiology & Infection Control'),
(1, 79, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'A blood culture should be taken:', '["Before starting antibiotics, using strict aseptic technique", "Without skin cleaning", "From the arm with the drip running, after the first antibiotic dose", "After antibiotics are given"]'::jsonb, 0, 'Contamination causes false-positive results.', 'GSM 402 · Microbiology & Infection Control'),
(1, 80, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'An antiseptic differs from a disinfectant because an antiseptic is:', '["Used on living tissue such as skin", "Used only on floors", "Always a sterilant that kills spores on instruments", "Stronger than all disinfectants"]'::jsonb, 0, 'Disinfectants are for inanimate objects.', 'GSM 402 · Microbiology & Infection Control'),
(1, 81, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Exogenous infection means infection from:', '["An allergic reaction to the patient''s own skin bacteria", "Genetic disease", "Sources outside the patient, e.g. staff hands or equipment", "The patient''s own flora"]'::jsonb, 2, 'Asepsis and hand hygiene prevent it.', 'GSM 402 · Microbiology & Infection Control'),
(1, 82, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Contaminated linen from an infected patient should be:', '["Mixed with clean linen", "Placed in a labelled, water-soluble or red bag and not shaken", "Washed by hand on the ward", "Shaken out in the corridor and then sent with the normal laundry"]'::jsonb, 1, 'Shaking releases organisms into the air.', 'GSM 402 · Microbiology & Infection Control'),
(1, 83, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Cohort nursing means:', '["Sending infected patients home early so that the ward is cleared", "Grouping patients with the same infection together with dedicated staff", "Nursing only one patient per ward", "Mixing all patients together"]'::jsonb, 1, 'It is used when single rooms are not available.', 'GSM 402 · Microbiology & Infection Control'),
(1, 84, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Typhoid fever is caused by:', '["Shigella", "Clostridium tetani", "Vibrio cholerae", "Salmonella Typhi"]'::jsonb, 3, 'It can cause ileal perforation needing surgery.', 'GSM 402 · Microbiology & Infection Control'),
(1, 85, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Tetanus toxin causes:', '["Skin rash only", "Muscle weakness and floppiness", "Diarrhoea and dehydration from toxin in the gut", "Muscle spasms and lockjaw by blocking inhibitory nerves"]'::jsonb, 3, 'Keep patients in a quiet, dark environment.', 'GSM 402 · Microbiology & Infection Control'),
(1, 86, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'A suspected Lassa fever patient needing surgery requires:', '["Full PPE, isolation and strict sharps safety", "Standard gloves only, as for any other surgical patient", "Surgery in the general ward", "No special precautions"]'::jsonb, 0, 'Person-to-person spread through blood and body fluids occurs.', 'GSM 402 · Microbiology & Infection Control'),
(1, 87, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Escherichia coli is a common cause of:', '["Tetanus after deep puncture wounds", "Leprosy", "Urinary tract and abdominal wound infections", "Gas gangrene"]'::jsonb, 2, 'It is a Gram-negative rod from the gut.', 'GSM 402 · Microbiology & Infection Control'),
(1, 88, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Fever caused by infection is mainly due to:', '["Low blood sugar", "Pyrogens acting on the hypothalamus", "The lungs only", "The kidneys failing to clear excess heat"]'::jsonb, 1, 'Pyrogens reset the body temperature set point.', 'GSM 402 · Microbiology & Infection Control'),
(1, 89, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Streptococcus pyogenes (Group A) commonly causes:', '["Malaria and typhoid fever in children", "Cellulitis, tonsillitis and necrotising fasciitis", "Typhoid fever", "Tuberculosis"]'::jsonb, 1, 'It is Gram-positive cocci in chains.', 'GSM 402 · Microbiology & Infection Control'),
(1, 90, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Infection control audits in theatre help to:', '["Replace hand hygiene", "Check compliance with standards and improve practice", "Increase infection rates", "Punish staff who are found not to follow the rules"]'::jsonb, 1, 'Feedback improves practice.', 'GSM 402 · Microbiology & Infection Control'),
(1, 91, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'One of these is a method of isolation __________', '["Strick universal precaution", "Ultraclean wards", "Segregation into single rooms", "Infectious disease unit"]'::jsonb, 2, 'Isolating patients in single rooms (segregation) is a basic method of isolation.', 'GSM 402 · Microbiology & Infection Control'),
(1, 92, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Barrier nursing, as classically defined, aims to:', '["Protect the patient from others", "Protect others from the patient", "Have no protective purpose", "Only apply to surgical patients"]'::jsonb, 1, 'Standard barrier nursing (source isolation) is about preventing an infected patient from spreading disease to others.', 'GSM 402 · Microbiology & Infection Control'),
(1, 93, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'For surgical prophylaxis, the antibiotic dose should ideally be given:', '["Just before surgery", "Only after the surgery is completed", "Timing does not matter", "More than 2 hours before surgery"]'::jsonb, 0, 'Giving the dose just before incision ensures adequate drug levels are present in the tissue during the highest-risk period; more than 2 hours before is considered wasted timing.', 'GSM 402 · Microbiology & Infection Control'),
(1, 94, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'A patient on a mechanical ventilator develops new fever, purulent secretions, and a new infiltrate on chest X-ray after 4 days of ventilation. This presentation is most consistent with:', '["Pulmonary embolism", "Ventilator-Associated Pneumonia (VAP)", "Simple atelectasis with no infection", "Normal expected findings on a ventilator"]'::jsonb, 1, 'New fever, purulent secretions and a new infiltrate after several days of mechanical ventilation are classic diagnostic features of VAP.', 'GSM 402 · Microbiology & Infection Control'),
(1, 95, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'HIV post-exposure prophylaxis should be started:', '["Only after the source patient''s HIV test result has returned after a month", "Only after the patient''s test result returns in a month", "As soon as possible, ideally within 1–2 hours and no later than 72 hours", "After 1 week"]'::jsonb, 2, 'It is continued for 28 days.', 'GSM 402 · Microbiology & Infection Control'),
(1, 96, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'A Gram-negative diplococcus causing urethral discharge and newborn eye infection is:', '["Candida albicans", "Staphylococcus aureus", "Neisseria gonorrhoeae", "Clostridium tetani"]'::jsonb, 2, 'Neisseria meningitidis causes meningitis.', 'GSM 402 · Microbiology & Infection Control'),
(1, 97, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Malaria in Nigeria is mostly caused by:', '["Leishmania donovani", "Plasmodium falciparum", "Plasmodium vivax", "Trypanosoma"]'::jsonb, 1, 'It is transmitted by female Anopheles mosquitoes.', 'GSM 402 · Microbiology & Infection Control'),
(1, 98, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'The chain of infection includes the agent, reservoir, portal of exit, mode of transmission, portal of entry and:', '["Healthy staff", "Susceptible host", "Sterile equipment", "Clean environment"]'::jsonb, 1, 'Breaking any link stops transmission.', 'GSM 402 · Microbiology & Infection Control'),
(1, 99, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'The correct hand-washing technique should take about:', '["About 5 minutes, scrubbing to the elbows", "5 minutes", "40–60 seconds", "5 seconds"]'::jsonb, 2, 'Alcohol rub takes about 20–30 seconds.', 'GSM 402 · Microbiology & Infection Control'),
(1, 100, 'Perioperative Mock — Day 3 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'The BCG vaccine protects mainly against:', '["Severe forms of tuberculosis in children", "Tetanus", "Measles and rubella in young children", "Hepatitis B"]'::jsonb, 0, 'It is given at birth in Nigeria.', 'GSM 402 · Microbiology & Infection Control'),
(2, 1, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Etomidate is useful in shocked patients because of cardiovascular stability, but it can cause:', '["Adrenal suppression", "Severe bronchospasm", "Malignant hyperthermia", "Raised intracranial pressure"]'::jsonb, 0, 'It inhibits cortisol synthesis.', 'PAN 414 · Anaesthesia'),
(2, 2, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'The ''LEMON'' airway assessment includes Look, Evaluate 3-3-2, Mallampati, Obstruction and:', '["Neck mobility", "Nasal patency", "Nil by mouth status", "Number of teeth"]'::jsonb, 0, 'Each item flags a possible difficult airway.', 'PAN 414 · Anaesthesia'),
(2, 3, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'A patient with well-controlled hypertension and no functional limitation is classified as which ASA physical status?', '["ASA III", "ASA I", "ASA II", "ASA IV"]'::jsonb, 2, 'ASA II describes a patient with mild systemic disease and no substantive functional limitation, such as well-controlled hypertension or diabetes.', 'PAN 414 · Anaesthesia'),
(2, 4, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'The usual endotracheal tube cuff pressure target is:', '["20–30 cmH₂O", "80–100 cmH₂O", "5–10 cmH₂O", "50–60 cmH₂O"]'::jsonb, 0, 'Higher pressure causes tracheal mucosal ischaemia; lower risks aspiration.', 'PAN 414 · Anaesthesia'),
(2, 5, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'A commonly used first-line antiemetic for postoperative nausea and vomiting prophylaxis is:', '["Morphine", "Atropine", "Succinylcholine", "Ondansetron"]'::jsonb, 3, 'Ondansetron, a 5-HT3 receptor antagonist, is a standard first-line agent for prevention and treatment of postoperative nausea and vomiting.', 'PAN 414 · Anaesthesia'),
(2, 6, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'An advantage of nasotracheal intubation is:', '["Greater tube movement", "Easier oral hygiene", "Lower infection risk", "Less mucosal damage and bleeding"]'::jsonb, 1, 'A nasal tube leaves the mouth free for oral hygiene and is better tolerated and more stable long term. It carries risks of epistaxis and sinusitis.', 'PAN 414 · Anaesthesia'),
(2, 7, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'After intubation, breath sounds are heard only on the right side. The likely cause is:', '["Left tension pneumothorax only", "Endobronchial (right main bronchus) intubation", "Oesophageal intubation with gas entering the stomach", "Normal finding after intubation"]'::jsonb, 1, 'Withdraw the tube slightly while listening, then re-secure.', 'PAN 414 · Anaesthesia'),
(2, 8, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Nitrous oxide should be avoided in a patient with:', '["Mild iron-deficiency anaemia before elective surgery", "Pneumothorax or bowel obstruction", "A simple hand fracture", "Well-controlled hypertension"]'::jsonb, 1, 'N₂O diffuses into air-filled spaces and expands them.', 'PAN 414 · Anaesthesia'),
(2, 9, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'To reduce post dural puncture head ache with spinal we use', '["Small fine spinal needle", "Syringe", "Tohy needle", "Wide bore spinal needle"]'::jsonb, 0, 'Using a smaller-gauge (fine) spinal needle reduces the size of the dural puncture and lowers the risk of post-dural puncture headache.', 'PAN 414 · Anaesthesia'),
(2, 10, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'A hypoxic guard on an anaesthetic machine ensures that:', '["Volatile agents cannot be given", "Nitrous oxide is always delivered at a fixed concentration of 70%", "The ventilator cannot be turned off", "The delivered fresh gas contains at least about 25% oxygen"]'::jsonb, 3, 'It links oxygen and N₂O flowmeters mechanically or electronically.', 'PAN 414 · Anaesthesia'),
(2, 11, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'A caudal block is commonly used in:', '["Adults having neck dissection or thyroid surgery for analgesia", "Adults for thyroid surgery", "Eye surgery in the elderly", "Children for lower abdominal and perineal surgery analgesia"]'::jsonb, 3, 'It is an epidural injection through the sacral hiatus.', 'PAN 414 · Anaesthesia'),
(2, 12, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Hypoxia during general anaesthesia refers to:', '["Elevated body temperature", "Excess oxygen delivery to tissues", "Low blood glucose", "Inadequate oxygen delivery to tissues"]'::jsonb, 3, 'Hypoxia is inadequate tissue oxygenation, a critical complication to detect and correct promptly during anaesthesia.', 'PAN 414 · Anaesthesia'),
(2, 13, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'In a patient with sickle cell disease, the anaesthetic team must avoid:', '["Oxygen supplementation", "Warming blankets", "Hypoxia, dehydration, hypothermia and acidosis", "Giving IV fluids and oxygen, because they trigger sickling crises"]'::jsonb, 2, 'These trigger sickling and crises.', 'PAN 414 · Anaesthesia'),
(2, 14, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'A patient is extubated ''awake'' rather than ''deep'' mainly when:', '["There is a risk of aspiration or a difficult airway", "The patient is a child with a cold", "The surgeon is in a hurry and the next case is ready to start", "The patient has mild asthma only"]'::jsonb, 0, 'Awake patients can protect their own airway.', 'PAN 414 · Anaesthesia'),
(2, 15, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Which inhalational agent has the lowest blood–gas solubility coefficient?', '["Nitrous oxide", "Desflurane", "Isoflurane", "Sevoflurane"]'::jsonb, 1, 'Desflurane has the lowest blood–gas partition coefficient (about 0.42) of these agents, so its onset and offset are fastest.', 'PAN 414 · Anaesthesia'),
(2, 16, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'A thyromental distance of less than 6 cm on airway assessment suggests:', '["Normal neck movement", "A need for a smaller face mask", "A likely difficult laryngoscopy", "An easy intubation with a full view of the cords"]'::jsonb, 2, 'Other predictors: Mallampati III–IV, limited mouth opening and neck extension.', 'PAN 414 · Anaesthesia'),
(2, 17, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Clear fluids before elective surgery in children are usually allowed up to:', '["12 hours before anaesthesia", "6 hours before anaesthesia", "Only up to 6 hours before anaesthesia, the same as for solid food", "1 hour before anaesthesia (per many current guidelines)"]'::jsonb, 3, 'Breast milk is allowed up to 4 hours and formula up to 6 hours.', 'PAN 414 · Anaesthesia'),
(2, 18, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'A recognised side effect of rapid high-dose fentanyl is:', '["Chest wall rigidity", "Hypertension", "Tachycardia", "Abdominal pain"]'::jsonb, 0, 'High-dose, rapid IV fentanyl can cause chest wall (truncal) rigidity that makes ventilation hard. It is reversed with naloxone or a muscle relaxant.', 'PAN 414 · Anaesthesia'),
(2, 19, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Vasoconstrictors (e.g. adrenaline) added to local anaesthetics are contraindicated in:', '["Spinal anaesthesia", "Epidural anaesthesia", "Digital nerve block", "Regional anaesthesia"]'::jsonb, 2, 'Adrenaline-containing local anaesthetics are avoided in digital (finger/toe), penile and similar end-artery blocks because of the risk of ischaemia.', 'PAN 414 · Anaesthesia'),
(2, 20, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Pencil-point (e.g. Whitacre) spinal needles are preferred because they:', '["Allow an epidural catheter to pass", "Inject the local anaesthetic faster and with less resistance", "Are easier to see on X-ray", "Reduce the risk of post-dural puncture headache"]'::jsonb, 3, 'They part the dural fibres instead of cutting them.', 'PAN 414 · Anaesthesia'),
(2, 21, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'For caesarean section under spinal anaesthesia, the sensory block should reach about:', '["C4 (shoulder)", "T4 (nipple level)", "L1 (groin level), so the legs remain able to move", "S2 (perineum)"]'::jsonb, 1, 'This blocks peritoneal discomfort during surgery.', 'PAN 414 · Anaesthesia'),
(2, 22, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Which anaesthetic agent does NOT trigger malignant hyperthermia?', '["Halothane", "Isoflurane", "Suxamethonium", "Thiopentone"]'::jsonb, 3, 'Volatile agents (halothane, isoflurane) and suxamethonium trigger malignant hyperthermia. IV agents like thiopentone and propofol are safe.', 'PAN 414 · Anaesthesia'),
(2, 23, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'A gum elastic bougie is used during intubation to:', '["Replace the laryngoscope blade", "Measure the pressure inside the endotracheal tube cuff", "Guide the tube when the glottis is only partly seen", "Suction secretions from the trachea"]'::jsonb, 2, 'The tube is railroaded over the bougie into the trachea.', 'PAN 414 · Anaesthesia'),
(2, 24, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Remifentanil is very short-acting because it is metabolised by:', '["The liver only, over many hours", "The kidney only, so it accumulates in renal failure", "Non-specific blood and tissue esterases", "Plasma cholinesterase deficiency"]'::jsonb, 2, 'Plan other analgesia before it is stopped.', 'PAN 414 · Anaesthesia'),
(2, 25, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Factor at increase risk of aspiration includes:', '["chewing gum", "Two hours preoperative oral clear fluid administration", "drinking clear fluids 8 hours before operation", "gastro esophageal reflux"]'::jsonb, 3, 'Gastro-oesophageal reflux increases the risk of regurgitation and pulmonary aspiration during induction of anaesthesia.', 'PAN 414 · Anaesthesia'),
(2, 26, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Which drug is used to treat postoperative shivering?', '["Suxamethonium", "Pethidine", "Thiopentone", "Atropine"]'::jsonb, 1, 'Pethidine (meperidine) is very effective against postoperative shivering. Tramadol and clonidine are alternatives.', 'PAN 414 · Anaesthesia'),
(2, 27, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'A nurse is administering Ketamine to a patient for a procedural sedation. The nurse should be aware of which of the following side effects?', '["Bradycardia and hypotension", "Respiratory depression and hypothermia", "Hallucinations and increased salivation", "Hypoglycemia"]'::jsonb, 2, 'Ketamine is a dissociative anesthetic that can cause hallucinations and vivid dreams as the patient emerges from the sedation. It can also cause an increase in salivation, which requires the nurse to monitor for and manage secretions to prevent aspiration.', 'PAN 414 · Anaesthesia'),
(2, 28, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'The anaesthetic gas scavenging system (AGSS) is used to:', '["Warm and humidify inspired gases", "Recycle oxygen back to the patient", "Measure the end-tidal CO₂ and gas concentrations in the circuit", "Remove waste anaesthetic gases and protect theatre staff"]'::jsonb, 3, 'Long-term exposure to waste gases may harm staff.', 'PAN 414 · Anaesthesia'),
(2, 29, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'An anaesthetic agent contraindicated in hypertensive patients is:', '["Ketamine", "Diazepam", "Propofol", "Thiopentone sodium"]'::jsonb, 0, 'Ketamine stimulates the sympathetic nervous system, raising BP and heart rate, so avoid it in uncontrolled hypertension.', 'PAN 414 · Anaesthesia'),
(2, 30, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'The Jackson-Rees (Mapleson F) breathing system is mainly used for:', '["Long-term ICU ventilation", "Elderly adults only", "Children", "Obstetric spinal anaesthesia"]'::jsonb, 2, 'It has low resistance and a bag that shows spontaneous breathing.', 'PAN 414 · Anaesthesia'),
(2, 31, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Mendelson''s syndrome is:', '["A type of spinal headache", "Chemical pneumonitis from aspiration of acidic gastric contents", "A heart rhythm problem caused by volatile anaesthetic agents", "Allergy to latex gloves"]'::jsonb, 1, 'Risk is higher in pregnancy, obesity and full stomach.', 'PAN 414 · Anaesthesia'),
(2, 32, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Oral airway is contraindicated in one of the following conditions', '["Pediatric patient", "Full conscious patient", "Deeply anaesthetized patients", "Comatose patient"]'::jsonb, 1, 'An oropharyngeal (oral) airway can trigger gagging, laryngospasm, or vomiting in a fully conscious patient with intact airway reflexes, so it is reserved for the unconscious/obtunded.', 'PAN 414 · Anaesthesia'),
(2, 33, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'The definitive drug treatment for malignant hyperthermia is:', '["Flumazenil", "Dantrolene", "Naloxone", "Neostigmine"]'::jsonb, 1, 'Dantrolene works by inhibiting calcium release from the sarcoplasmic reticulum, directly reversing the hypermetabolic muscle crisis of malignant hyperthermia.', 'PAN 414 · Anaesthesia'),
(2, 34, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Diffusion hypoxia at the end of a nitrous oxide anaesthetic is prevented by:', '["Increasing the N₂O to 80%", "Giving 100% oxygen for a few minutes after stopping N₂O", "Giving IV naloxone at the end of surgery to reverse the opioids", "Turning off all gases at once"]'::jsonb, 1, 'N₂O floods into the alveoli and dilutes oxygen.', 'PAN 414 · Anaesthesia'),
(2, 35, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'The preferred muscle relaxant in a patient with liver or renal failure is:', '["Vecuronium", "Rocuronium", "Pancuronium", "Atracurium"]'::jsonb, 3, 'Atracurium (and cisatracurium) is broken down by Hofmann elimination and ester hydrolysis, without needing the liver or kidneys.', 'PAN 414 · Anaesthesia'),
(2, 36, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'A patient with status epilepticus is receiving midazolam. Which reversal agent is on standby?', '["Glucagon", "Naloxone", "Protamine", "Flumazenil"]'::jsonb, 3, 'Flumazenil reverses benzodiazepines like midazolam.', 'PAN 412 · Pharmacology'),
(2, 37, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'A patient with atrial fibrillation is started on amiodarone. The nurse should monitor for:', '["Pulmonary fibrosis", "Diarrhea", "Hypoglycemia", "Hypertension"]'::jsonb, 0, 'Amiodarone can cause pulmonary fibrosis, thyroid dysfunction, and liver toxicity.', 'PAN 412 · Pharmacology'),
(2, 38, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'The second-line drug of choice for status epilepticus, given as an IV loading dose, is:', '["Salbutamol", "Phenytoin", "Adrenaline", "Lorazepam"]'::jsonb, 1, 'Phenytoin is used when first-line benzodiazepines alone haven''t stopped the seizure.', 'PAN 412 · Pharmacology'),
(2, 39, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Naloxone is administered to a patient in the Emergency room. This is an antidote for for which of the following type of poisoning?', '["Alcohol overdose", "Chlorine poisoning", "Opiate poisoning", "Tricyclic antidepressant use"]'::jsonb, 2, 'Naloxone is the specific opioid antagonist/antidote.', 'PAN 412 · Pharmacology'),
(2, 40, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Which of the following is not a weak opioid?', '["Tramadol", "Hydromorphone", "Codeine", "Hydrocodone"]'::jsonb, 1, 'Hydromorphone is a strong (not weak) opioid, unlike codeine, tramadol, and hydrocodone.', 'PAN 412 · Pharmacology'),
(2, 41, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'The relationship between drug concentration and time is studied in:', '["Pharmacokinetics", "Pharmacogenomics", "Pharmacodynamics", "Pharmacovigilance"]'::jsonb, 0, 'Pharmacokinetics is what the body does to the drug (absorption, distribution, metabolism, excretion), i.e. drug concentration over time.', 'PAN 412 · Pharmacology'),
(2, 42, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Flumazenil, used to reverse benzodiazepine sedation, should be used cautiously in patients who:', '["Are undergoing routine anaesthesia reversal only", "Have never taken benzodiazepines", "Have normal renal function", "Are chronic benzodiazepine users, due to seizure risk"]'::jsonb, 3, 'In chronic benzodiazepine users, flumazenil can precipitate acute withdrawal and seizures by abruptly reversing tolerance-related GABA receptor effects.', 'PAN 412 · Pharmacology'),
(2, 43, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'To ensure homogenization when diluting powdered medication in a vial, the nurse should:', '["Roll the vial gently between the palms.", "Do nothing after adding the solution to the vial.", "Shake the vial vigorously.", "Invert the vial and let it stand for 1 minute."]'::jsonb, 0, 'Roll the vial gently to mix the powder. Shaking causes foaming and can damage some drugs.', 'PAN 412 · Pharmacology'),
(2, 44, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'A patient is prescribed an ACE inhibitor for hypertension. The nurse should monitor for which characteristic side effect?', '["Improved potassium excretion with no monitoring needed", "Persistent dry cough", "Hair loss", "Significant weight gain only"]'::jsonb, 1, 'ACE inhibitors are classically associated with a persistent dry cough (related to bradykinin accumulation), a common reason for switching to an ARB if troublesome.', 'PAN 412 · Pharmacology'),
(2, 45, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Which drug is effective in treating oral candidiasis?', '["Griseofulvin", "Tetracycline", "Nystatin", "Bacitracin"]'::jsonb, 2, 'Nystatin is a polyene antifungal used topically and orally for oral candidiasis (thrush).', 'PAN 412 · Pharmacology'),
(2, 46, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Prophylactic antibiotics given before surgery are ideally administered:', '["Within about 60 minutes before surgical incision", "Only if the patient develops a fever post-operatively", "More than 6 hours before incision", "Only after the wound is closed"]'::jsonb, 0, 'Surgical antibiotic prophylaxis is most effective when given within roughly 60 minutes before incision, ensuring adequate tissue levels at the time of surgery.', 'PAN 412 · Pharmacology'),
(2, 47, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Gastric lavage is contraindicated in which of the following situations?', '["General sedative overdose within 1 hour", "Within 2 hours of a large tablet overdose", "Corrosive/acid ingestion", "Barbiturate overdose while still conscious"]'::jsonb, 2, 'Passing a tube for a corrosive substance risks further damage to the oesophagus and stomach.', 'PAN 412 · Pharmacology'),
(2, 48, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Protamine sulfate is used to reverse the anticoagulant effect of:', '["Aspirin", "Warfarin", "Clopidogrel", "Heparin"]'::jsonb, 3, 'Protamine sulfate binds and neutralises heparin, reversing its anticoagulant effect.', 'PAN 412 · Pharmacology'),
(2, 49, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Analgesic drug selection in a critically ill patient should be guided primarily by:', '["A validated pain assessment tool and the severity/type of pain", "Avoiding all analgesia to prevent sedation", "The cheapest available option regardless of pain severity", "The nurse''s personal preference"]'::jsonb, 0, 'Analgesic choice and dosing should be guided by structured pain assessment (using a validated pain scale) matched to the severity and nature of the patient''s pain.', 'PAN 412 · Pharmacology'),
(2, 50, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'During adult cardiac arrest, IV adrenaline (epinephrine) is administered at what dose and interval?', '["10mg once only", "1mg every 15 minutes", "1mg every 3–5 minutes", "0.1mg every 1 minute"]'::jsonb, 2, 'Standard ACLS dosing is 1mg IV adrenaline every 3–5 minutes during cardiac arrest resuscitation.', 'PAN 412 · Pharmacology'),
(2, 51, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'A patient receiving cyclosporine post-transplant has hypertension. Which drug is CONTRAINDICATED?', '["Nifedipine", "Amlodipine", "Lisinopril", "Verapamil"]'::jsonb, 3, 'Verapamil increases cyclosporine levels via CYP3A4 inhibition, risking toxicity.', 'PAN 412 · Pharmacology'),
(2, 52, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'A patient on dopamine at 15 mcg/kg/min is likely to experience:', '["Renal artery dilation", "Bronchospasm", "Hyperglycemia", "Vasoconstriction"]'::jsonb, 3, 'High-dose dopamine (>10 mcg/kg/min) activates α-receptors, causing vasoconstriction.', 'PAN 412 · Pharmacology'),
(2, 53, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'When administering furosemide, the nurse should closely monitor for:', '["Hypoglycaemia specifically caused by the drug", "Hyperkalaemia", "Bradycardia as the primary risk", "Hypokalaemia and other electrolyte disturbances"]'::jsonb, 3, 'Furosemide, a loop diuretic, promotes potassium (and other electrolyte) losses in the urine, making electrolyte monitoring essential during therapy.', 'PAN 412 · Pharmacology'),
(2, 54, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'A patient receiving IV insulin for hyperglycemia should be monitored for:', '["Hypokalemia", "Hypernatremia", "Hypermagnesemia", "Hypocalcemia"]'::jsonb, 0, 'Insulin shifts K⁺ intracellularly, causing hypokalemia.', 'PAN 412 · Pharmacology'),
(2, 55, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'A patient receiving vancomycin has flushing, rash, and hypotension. Which action is BEST?', '["Stop infusion and administer diphenhydramine", "Administer epinephrine", "Switch to oral vancomycin", "Increase infusion rate to complete dose"]'::jsonb, 0, 'Red man syndrome is a histamine-mediated reaction. Stopping the infusion and giving antihistamines is standard.', 'PAN 412 · Pharmacology'),
(2, 56, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'A patient on warfarin has an INR of 8.0. Which reversal agent is used for active bleeding?', '["Protamine sulfate", "Andexanet alfa", "FFP", "Vitamin K IV"]'::jsonb, 2, 'FFP provides immediate clotting factors for warfarin reversal. Vitamin K works slowly.', 'PAN 412 · Pharmacology'),
(2, 57, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'A patient taking ibuprofen 400 mg twice daily for chronic back pain develops leg oedema. This is most likely caused by:', '["A low creatinine level", "A decrease in renal function", "An increase in plasma proteins", "An increased glomerular filtration rate"]'::jsonb, 1, 'NSAIDs block renal prostaglandins, reducing renal blood flow and GFR and causing sodium and water retention and oedema.', 'PAN 412 · Pharmacology'),
(2, 58, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'The antidote for paracetamol overdose is:', '["Atropine", "Naloxone", "Acetylcysteine", "Flumazenil"]'::jsonb, 2, 'Acetylcysteine replenishes liver glutathione, helping detoxify the harmful paracetamol breakdown product.', 'PAN 412 · Pharmacology'),
(2, 59, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Propofol infusion syndrome is a rare but serious complication associated with:', '["Short-term, low-dose propofol use", "Prolonged, high-dose propofol infusion", "Dexmedetomidine use", "Fentanyl use"]'::jsonb, 1, 'Propofol infusion syndrome, involving metabolic acidosis, rhabdomyolysis, and cardiac failure, is associated with prolonged high-dose propofol infusions, particularly in critically ill patients.', 'PAN 412 · Pharmacology'),
(2, 60, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Vitamin K is used to reverse excessive anticoagulation from which drug?', '["Warfarin", "Aspirin", "Heparin", "Enoxaparin"]'::jsonb, 0, 'Vitamin K restores synthesis of clotting factors suppressed by warfarin, reversing its anticoagulant effect (though onset is slower than with prothrombin complex concentrate).', 'PAN 412 · Pharmacology'),
(2, 61, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'The specific antidote for benzodiazepine overdose is:', '["Protamine sulfate", "Dantrolene", "Flumazenil", "Naloxone"]'::jsonb, 2, 'Flumazenil is a competitive benzodiazepine receptor antagonist used to reverse benzodiazepine sedation/overdose.', 'PAN 412 · Pharmacology'),
(2, 62, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'A patient on high-dose corticosteroids is at risk for:', '["Adrenal suppression", "Hyperkalemia", "Hypothyroidism", "Hypoglycemia"]'::jsonb, 0, 'Chronic steroids suppress the HPA axis, requiring stress-dose coverage.', 'PAN 412 · Pharmacology'),
(2, 63, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Before giving morphine 4 mg IV for incisional pain, the nurse should:', '["Assess the patient''s respiratory status", "Monitor the heart rate only", "Clarify the order with the prescriber", "Assess the incision"]'::jsonb, 0, 'Opioids depress respiration, so check respiratory rate and sedation before giving IV morphine.', 'PAN 412 · Pharmacology'),
(2, 64, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'A patient with septic shock is started on vasopressin. Which effect is expected?', '["Coronary vasodilation", "Increased urine output", "Vasoconstriction", "Decreased SVR"]'::jsonb, 2, 'Vasopressin is a potent vasoconstrictor used in refractory septic shock.', 'PAN 412 · Pharmacology'),
(2, 65, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Which of the following is a thrombolytic agent?', '["Streptokinase", "Warfarin sodium", "Heparin", "Clexane (enoxaparin)"]'::jsonb, 0, 'Streptokinase (like alteplase) is a thrombolytic that dissolves clots. Heparin, enoxaparin (Clexane) and warfarin are anticoagulants that only stop clots growing.', 'PAN 412 · Pharmacology'),
(2, 66, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A patient in PACU after a regional block has a numb, weak arm. The nurse should:', '["Protect the limb in a sling and explain sensation will return", "Tell the patient that the numbness is likely to be permanent", "Apply a hot water bottle to the arm to speed up the return of sensation", "Start vigorous arm exercises at once to restore the feeling"]'::jsonb, 0, 'Numb limbs are at risk of injury.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 67, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A patient s/p abdominal surgery has a BP of 85/50 mmHg and HR 120 bpm. The nurse suspects:', '["Atelectasis", "Pain", "Infection", "Hemorrhage"]'::jsonb, 3, 'Tachycardia and hypotension indicate hypovolemia (e.g., bleeding).', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 68, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A patient has a PCA and becomes very drowsy with RR 8/min. After calling for help and giving oxygen, the nurse should:', '["Stop the PCA and prepare naloxone", "Give an IV sedative", "Encourage the patient to press the button", "Increase the PCA bolus"]'::jsonb, 0, 'Sedation score rises before respiratory depression.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 69, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A patient s/p abdominal surgery has fever and purulent wound drainage on day 7. The nurse suspects:', '["Atelectasis", "Pneumonia", "Wound infection", "UTI"]'::jsonb, 2, 'Wound infections typically present on days 5-7.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 70, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A patient in PACU had surgery on the leg under a tourniquet and a cast. The nurse must check:', '["Only the patient''s hearing, after the long anaesthetic", "Only the blood glucose, as other checks are not needed", "Neurovascular status: colour, warmth, pulses and sensation", "Only the level of the oxygen cylinder that is attached to the bed frame"]'::jsonb, 2, 'Report pain out of proportion, which may be compartment syndrome.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 71, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A patient is at risk for developing post-operative hypothermia. What nursing interventions can help prevent hypothermia in the post-operative period?', '["Monitor the patient''s temperature regularly", "Limit the use of warm fluids and blankets", "Keep the patient''s room temperature cool", "Use warming blankets or forced-air warming devices"]'::jsonb, 3, 'Active warming measures (warmed blankets, forced-air warmers) help prevent and treat postoperative hypothermia.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 72, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A patient''s urine output in PACU is 10 mL/h for 2 hours after major surgery (70 kg). The nurse should:', '["Give a diuretic straight away to increase the output, without assessment", "Check the catheter, assess fluid status and inform the doctor", "Do nothing, as this output is normal after major surgery", "Remove the catheter and wait for the patient to void"]'::jsonb, 1, 'Target is at least 0.5 mL/kg/h (35 mL/h here).', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 73, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A patient in PACU is distressed and pulling at lines after waking. The nurse should first:', '["Apply physical restraints to all four limbs at once", "Look for hypoxia, pain or a full bladder, and reorient", "Give a large IV dose of benzodiazepine immediately to calm the patient", "Leave them to settle alone with the curtains closed"]'::jsonb, 1, 'Agitation may hide a serious cause.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 74, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A patient vomits blood-stained fluid in PACU after nasal surgery. This is most likely:', '["A sign of severe hypoglycaemia after fasting", "Normal bile from the stomach", "Swallowed blood from the operative site", "Upper GI cancer bleeding"]'::jsonb, 2, 'Monitor for ongoing bleeding from the nose.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 75, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A patient in PACU suddenly loses consciousness with no pulse. The nurse''s first action is to:', '["Check the blood glucose first", "Take the patient to the ward", "Give oral fluids", "Call for help and start CPR"]'::jsonb, 3, 'Follow ALS: defibrillate if shockable rhythm.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 76, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A patient with epidural analgesia has a sensory level at T4. The nurse monitors for:', '["Urinary retention", "Bradycardia", "Hypertension", "Respiratory depression"]'::jsonb, 3, 'High thoracic blocks can cause respiratory muscle weakness.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 77, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'An NSAID such as ibuprofen is avoided after surgery in a patient with:', '["A clean, small surgical wound", "A mild tension-type headache after the anaesthetic", "Normal kidney and liver function", "Acute kidney injury or active GI bleeding"]'::jsonb, 3, 'NSAIDs reduce renal blood flow and impair platelets.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 78, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Wound dehiscence is a potential complication postoperatively. What action should the nurse take if a patient''s wound begins to dehisce?', '["Apply a pressure dressing over the wound", "Notify the healthcare provider immediately", "Leave the wound open to air out", "Apply steri-strips to secure the wound edges"]'::jsonb, 1, 'Suspected wound dehiscence should be reported to the healthcare provider immediately so it can be assessed and managed before evisceration risk increases.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 79, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Which patient should be transferred from PACU to HDU or ICU rather than the ward?', '["One with stable observations and mild pain", "One who has passed urine", "One who is awake and talking", "One needing ongoing vasopressor support"]'::jsonb, 3, 'Use agreed criteria and escalation pathways.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 80, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'An LMA may be removed in PACU when the patient:', '["Is asleep with the cuff fully deflated", "Is awake and can open the mouth on command", "Starts to vomit with the cuff still inflated", "Is still deeply unconscious with no reflexes"]'::jsonb, 1, 'Removal technique varies; follow unit policy.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 81, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'With patient-controlled analgesia (PCA), the button should be pressed by:', '["Any visitor who sees pain", "The patient only", "The nurse every 5 minutes", "The family when the patient sleeps"]'::jsonb, 1, 'Pressing by others (''PCA by proxy'') can cause overdose.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 82, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A patient in PACU after carotid surgery should be closely monitored for:', '["Blood in the urine and loin pain from the urinary catheter", "Neck haematoma, BP changes and new neurological signs", "Hearing loss and ringing in the ears", "Ankle oedema and calf tenderness only"]'::jsonb, 1, 'Stroke and airway compression are key risks.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 83, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'The Bromage score is used to assess:', '["Postoperative nausea and vomiting", "Level of sedation after anaesthesia", "Motor block of the legs after spinal or epidural", "Pain intensity at rest and on movement on a 0–10 scale"]'::jsonb, 2, 'Increasing motor block on an epidural can signal a haematoma.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 84, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Opioid respiratory depression in PACU is reversed safely by:', '["Titrating small IV doses of naloxone", "Giving more morphine to settle the patient", "Giving flumazenil as the specific antidote", "Giving 2 mg naloxone at once to all patients"]'::jsonb, 0, 'Large doses cause severe pain and hypertension; naloxone may wear off before the opioid.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 85, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A PACU nurse receives a patient after spinal anaesthesia for knee surgery. Monitoring should include:', '["Only the respiratory rate each hour", "BP, block regression and urine output", "Only the patient''s appetite and thirst", "Only the wound site and dressing"]'::jsonb, 1, 'Urinary retention is common after spinal anaesthesia.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 86, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A PACU nurse sees that the patient''s oxygen tubing has become disconnected. This shows the importance of:', '["Turning off the alarms to reduce noise", "Using less monitoring on each patient so that alarms are rare", "Regular checks of equipment as well as the patient", "Leaving the bay unattended for short periods"]'::jsonb, 2, 'Look at the patient, then the monitor.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 87, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'The lockout interval on a morphine PCA (e.g. 5 minutes) is designed to:', '["Stop all analgesia during the night hours", "Allow a continuous high-dose background infusion", "Stop a new dose before the last one has worked", "Lock the pump so nobody can change the drug"]'::jsonb, 2, 'Typical bolus is 1 mg morphine.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 88, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A patient with obstructive sleep apnoea in PACU should be nursed:', '["Lying flat with no monitoring once they are awake and talking", "Flat on the back with large doses of opioids", "Sitting up with oxygen, and CPAP if used at home", "Alone in a side room to help them sleep"]'::jsonb, 2, 'They are very sensitive to opioids and sedatives.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 89, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A day-case patient being discharged home after general anaesthesia should:', '["Go home with a responsible adult and not drive for 24–48 h", "Drive themselves home if they feel fully alert after one hour in recovery", "Sign important legal documents the same evening", "Go home alone by public transport after an hour"]'::jsonb, 0, 'Give written instructions and a contact number.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 90, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Post-operative cognitive dysfunction (POCD) is:', '["A problem caused only by local anaesthetic drugs given during the surgery", "A decline in memory and thinking after surgery, mostly in older people", "A type of deep wound infection after major surgery", "A normal and expected finding in all young children"]'::jsonb, 1, 'It may last weeks to months.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 91, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A post-operative patient''s IV cannula site is red, swollen and painful. The nurse should:', '["Leave it in place and ignore it until the day of discharge from hospital", "Remove the cannula and re-site it if still needed", "Apply an extra dressing over the site", "Increase the infusion rate through it"]'::jsonb, 1, 'Use a phlebitis score to assess.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 92, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A nurse is caring for a patient who is post-anesthesia. The patient is experiencing nausea and vomiting. The nurse should:', '["Tell the patient to wait for the nausea to pass", "Encourage the patient to eat a large meal", "Place the patient in a prone position", "Administer an antiemetic as ordered"]'::jsonb, 3, 'Post-operative nausea and vomiting (PONV) is a common side effect of anesthesia. The nurse should administer an antiemetic as ordered to relieve the patient''s symptoms and prevent further complications like aspiration. The patient should not be encouraged to eat, and a prone position is not appropriate.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 93, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Ketorolac or other NSAIDs are useful in PACU because they:', '["Reduce opioid requirements", "Reverse muscle relaxants", "Cause deep sedation, so less monitoring is needed", "Prevent hypothermia"]'::jsonb, 0, 'Avoid in renal impairment, bleeding risk and asthma sensitive to NSAIDs.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 94, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A patient s/p pneumonectomy has sudden SOB and hypotension. The nurse suspects:', '["Pulmonary embolism", "Pneumonia", "Tension pneumothorax", "Myocardial infarction"]'::jsonb, 0, 'Immobility and surgery increase PE risk.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 95, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A patient in the postoperative period experiences delayed wound healing. Which factor should be assessed to determine the cause?', '["Blood pressure", "Blood glucose levels", "Respiratory rate", "White blood cell count"]'::jsonb, 1, 'Elevated blood glucose impairs wound healing, so glycaemic control is assessed as a contributing factor to delayed healing.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 96, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A diabetic patient in PACU is sweating, confused and tachycardic. The nurse should first check:', '["A chest X-ray film", "Serum sodium and potassium levels", "Capillary blood glucose", "Urine culture result"]'::jsonb, 2, 'Hypoglycaemia is quickly treatable with IV glucose.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 97, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A patient with a tracheostomy in PACU should have at the bedside:', '["Spare tubes (same size and smaller), suction and dilators", "Only a nasal cannula and an oxygen flowmeter", "A face mask and oxygen tubing, but no suction or spare tracheostomy tube", "A spare urinary catheter and drainage bag"]'::jsonb, 0, 'Displacement is an airway emergency.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 98, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A patient in PACU suddenly cannot speak and has new arm weakness. The nurse suspects:', '["Normal effect of the anaesthetic", "Low urine output from fasting", "Pain from the surgical wound causing the patient to refuse to talk", "Stroke; call for urgent medical review"]'::jsonb, 3, 'Note the time of onset; urgent imaging may be needed.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 99, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A patient in PACU has an SpO₂ of 88% on room air but is breathing well. The nurse should first:', '["Ignore it, as an SpO₂ of 88% is normal after any general anaesthetic", "Give a diuretic to clear fluid from the lungs", "Remove the probe and record a value of 100%", "Give oxygen and check the airway and the probe"]'::jsonb, 3, 'Hypoxaemia after anaesthesia is common; find the cause.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 100, 'Perioperative Mock — Day 3 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Oxygen therapy in PACU is commonly continued until the patient:', '["Has had a bowel movement after surgery", "Leaves the hospital to go home", "Maintains target SpO₂ on room air", "Has eaten a full meal on the ward"]'::jsonb, 2, 'Target is usually 94–98% (88–92% in CO₂ retainers).', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(3, 1, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 416 · General Surgery', 'Classic presenting features of appendicitis in a child include periumbilical pain migrating to which quadrant?', '["Left upper quadrant", "Right lower quadrant", "Left lower quadrant", "Right upper quadrant"]'::jsonb, 1, 'Appendicitis classically presents with pain that starts periumbilically and migrates to the right lower quadrant (McBurney''s point).', 'PON 416 · General Surgery'),
(3, 2, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 416 · General Surgery', 'The main goal of postoperative thyroidectomy care is:', '["Reducing anxiety", "Preventing dehydration", "Promoting sleep", "Maintaining airway patency"]'::jsonb, 3, 'Protecting the airway is always the top priority in post-thyroidectomy nursing care.', 'PON 416 · General Surgery'),
(3, 3, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 416 · General Surgery', 'An indirect inguinal hernia passes through the:', '["Femoral canal below the inguinal ligament", "Deep inguinal ring, lateral to the inferior epigastric vessels", "Hesselbach''s triangle, medial to the inferior epigastric vessels", "Linea alba above the umbilicus"]'::jsonb, 1, 'Direct hernias pass through Hesselbach''s triangle.', 'PON 416 · General Surgery'),
(3, 4, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 416 · General Surgery', 'Hydatid cysts of the liver are caused by:', '["Schistosoma mansoni (blood fluke)", "Plasmodium falciparum", "Entamoeba histolytica", "Echinococcus granulosus"]'::jsonb, 3, 'Spillage of cyst contents during surgery can cause anaphylaxis.', 'PON 416 · General Surgery'),
(3, 5, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 416 · General Surgery', 'An enterocutaneous fistula is:', '["A tear in the lining of the anal canal", "An abnormal link between bowel and skin", "A blocked common bile duct with jaundice", "A normal, planned surgical stoma"]'::jsonb, 1, 'Protect the skin and manage fluid and nutrition.', 'PON 416 · General Surgery'),
(3, 6, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 416 · General Surgery', 'A Sengstaken–Blakemore tube is used to:', '["Feed patients who have severe dysphagia", "Compress bleeding oesophageal varices", "Relieve acute urinary retention", "Drain bile from the liver after surgery"]'::jsonb, 1, 'It is a temporary measure; the airway must be protected.', 'PON 416 · General Surgery'),
(3, 7, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 416 · General Surgery', 'Melaena (black, tarry stool) is most suggestive of bleeding from:', '["Haemorrhoids", "The rectum", "The upper GI tract", "The appendix"]'::jsonb, 2, 'Blood digested over a long distance turns black and tarry — about 90% of the time this means an upper GI source.', 'PON 416 · General Surgery'),
(3, 8, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 416 · General Surgery', 'A patient with a new ileostomy is at particular risk of:', '["Hypercalcaemia and stones", "Fluid overload, oedema and weight gain", "Dehydration and electrolyte loss", "Constipation and hard stools"]'::jsonb, 2, 'Encourage fluids and report high output.', 'PON 416 · General Surgery'),
(3, 9, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 416 · General Surgery', 'An anal fissure is most commonly found:', '["In the posterior midline of the anal canal", "On the lateral buttock skin near the anus", "In the rectum well above the dentate line", "On the lateral perianal skin, away from the anal canal"]'::jsonb, 0, 'Treatment includes stool softeners and GTN or diltiazem ointment.', 'PON 416 · General Surgery'),
(3, 10, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 416 · General Surgery', 'Stoma output measurement is important because high output (over about 1.5 L/day) causes:', '["Hypertension and headaches", "Fluid overload, hypertension and peripheral oedema", "Hypercalcaemia and stones", "Dehydration, hypokalaemia and hypomagnesaemia"]'::jsonb, 3, 'Oral rehydration solutions and anti-motility drugs may be used.', 'PON 416 · General Surgery'),
(3, 11, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 416 · General Surgery', 'A seroma after mastectomy is:', '["Cancer recurrence in the chest wall under the scar", "An infection of the nipple and areola", "A blood clot in the deep veins of the leg", "A collection of serous fluid under the flaps"]'::jsonb, 3, 'It may be aspirated if large or uncomfortable.', 'PON 416 · General Surgery'),
(3, 12, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 416 · General Surgery', 'A patient with peritonitis typically lies:', '["Walking around the ward to ease the pain", "Rolling about in bed, unable to settle", "In a knee-chest position to ease pain", "Very still, as movement worsens the pain"]'::jsonb, 3, 'Patients with colic (e.g. renal) tend to move about.', 'PON 416 · General Surgery'),
(3, 13, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 416 · General Surgery', 'The most life-threatening intraoperative complication of thyroidectomy is:', '["Hypothyroidism", "Hoarseness", "Hemorrhage", "Hypocalcaemia"]'::jsonb, 2, 'Haemorrhage during thyroid surgery is life-threatening because of the gland''s rich blood supply and proximity to the airway.', 'PON 416 · General Surgery'),
(3, 14, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 416 · General Surgery', 'After laparoscopic cholecystectomy, increasing abdominal pain, fever and bile in the drain suggest:', '["Normal recovery", "Shoulder tip pain only", "Urinary retention", "Bile leak"]'::jsonb, 3, 'Report urgently; imaging or ERCP may be needed.', 'PON 416 · General Surgery'),
(3, 15, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 416 · General Surgery', 'A pilonidal abscess is managed by:', '["Long-term oral steroids to shrink the sinus", "Radiotherapy to the sacral area to shrink the sinus tract", "Incision and drainage, then later definitive surgery", "Ignoring it until it bursts on its own"]'::jsonb, 2, 'Hair removal and hygiene reduce recurrence.', 'PON 416 · General Surgery'),
(3, 16, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 416 · General Surgery', 'An upper GI endoscopy patient is kept nil by mouth afterwards until:', '["The throat anaesthetic wears off and gag returns", "Only for 5 minutes after the endoscope is removed", "They have passed urine after the procedure", "The next morning in all cases, whatever the time"]'::jsonb, 0, 'This prevents aspiration.', 'PON 416 · General Surgery'),
(3, 17, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 416 · General Surgery', 'What is an obvious sign of upper GI bleeding?', '["Hematemesis", "Abdominal pain", "Upset stomach", "Weight loss"]'::jsonb, 0, 'Vomiting blood (haematemesis) is the obvious direct sign of upper GI bleeding.', 'PON 416 · General Surgery'),
(3, 18, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 416 · General Surgery', 'Sentinel lymph node biopsy in breast cancer is done to:', '["Check if cancer has reached the first draining node", "Reconstruct the breast at the same operation", "Remove the whole breast and the chest wall muscles beneath it", "Treat lymphoedema of the arm after surgery"]'::jsonb, 0, 'A negative node may avoid full axillary clearance.', 'PON 416 · General Surgery'),
(3, 19, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 416 · General Surgery', 'The opening of a stoma appliance should be cut:', '["Twice the size of the stoma", "Exactly the size of the abdomen", "About 2–3 mm larger than the stoma", "Smaller than the stoma so it grips it"]'::jsonb, 2, 'This protects the skin without cutting into the stoma.', 'PON 416 · General Surgery'),
(3, 20, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 416 · General Surgery', 'An ingrown toenail with infection is commonly treated by:', '["Wedge excision of the nail edge with phenol", "Tight bandaging of the toe for a month", "Oral steroids for several weeks to reduce the swelling", "Amputation of the whole affected toe"]'::jsonb, 0, 'Phenol prevents regrowth of that edge.', 'PON 416 · General Surgery'),
(3, 21, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 416 · General Surgery', 'A wound infection after surgery most commonly appears around:', '["Within the first hour", "Day 30–60 after surgery", "After about one year", "Day 5–7 after surgery"]'::jsonb, 3, 'Signs include redness, swelling, pain, pus and fever.', 'PON 416 · General Surgery'),
(3, 22, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 416 · General Surgery', 'A patient after abdominal surgery has calf pain, swelling and warmth on day 8. The nurse suspects:', '["Muscle cramp only", "Deep vein thrombosis", "Paralytic ileus", "Superficial wound infection spreading down the leg"]'::jsonb, 1, 'Report and arrange Doppler ultrasound.', 'PON 416 · General Surgery'),
(3, 23, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 416 · General Surgery', 'The serum enzyme most commonly raised in acute pancreatitis is:', '["Creatine kinase", "Troponin", "Alkaline phosphatase only", "Amylase (or lipase)"]'::jsonb, 3, 'Levels above three times normal support the diagnosis.', 'PON 416 · General Surgery'),
(3, 24, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 416 · General Surgery', 'A colostomy stoma that turns dark purple or black after surgery suggests:', '["A normal, healthy stoma", "Stoma ischaemia or necrosis", "A mild skin allergy to the stoma bag adhesive", "Stoma prolapse only"]'::jsonb, 1, 'Report urgently to the surgeon.', 'PON 416 · General Surgery'),
(3, 25, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 416 · General Surgery', 'Pain on extension of the right hip in suspected appendicitis is called:', '["The psoas sign", "Kernig''s sign", "Murphy''s sign of the gallbladder", "Cullen''s sign"]'::jsonb, 0, 'It suggests a retrocaecal appendix irritating the psoas.', 'PON 416 · General Surgery'),
(3, 26, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 416 · General Surgery', 'A Hartmann''s procedure involves:', '["Removing the gallbladder through a small incision", "Joining the small bowel directly to the stomach", "Repairing a femoral hernia with a mesh plug and a drain", "Sigmoid resection, end colostomy and closed rectal stump"]'::jsonb, 3, 'It is often done for perforated diverticulitis.', 'PON 416 · General Surgery'),
(3, 27, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 416 · General Surgery', 'A thyroidectomy patient becomes restless, cyanosed, and has a neck swelling. The nurse should first:', '["Start IV fluids", "Remove sutures and call the surgeon", "Elevate the foot of the bed", "Reassure the patient"]'::jsonb, 1, 'Restlessness, cyanosis, and neck swelling suggest airway-compromising haematoma — sutures must be released immediately and the surgeon called.', 'PON 416 · General Surgery'),
(3, 28, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 416 · General Surgery', 'The patient post-thyroidectomy should report immediately if:', '["Appetite increases", "Voice becomes hoarse", "Sleep improves", "Weight increases"]'::jsonb, 1, 'New or worsening hoarseness should be reported promptly as a possible sign of nerve injury.', 'PON 416 · General Surgery'),
(3, 29, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 416 · General Surgery', 'Acute cholangitis treatment includes antibiotics, fluids and:', '["Immediate liver transplantation", "Oral antacids only, and wait", "Urgent biliary drainage, often by ERCP", "Full bowel preparation first, then a laparotomy next week"]'::jsonb, 2, 'Untreated cholangitis can cause septic shock.', 'PON 416 · General Surgery'),
(3, 30, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 416 · General Surgery', 'A patient on TPN after major GI surgery must be monitored closely for:', '["Hair growth and nail changes", "Hearing and balance tests", "Glucose, electrolytes and line infection", "Visual acuity in each eye and daily hearing tests"]'::jsonb, 2, 'TPN lines must be handled with strict asepsis.', 'PON 416 · General Surgery'),
(3, 31, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 416 · General Surgery', 'A patient with an ileostomy has high-output losses. The nurse is concerned about:', '["Hypokalemia", "Hypercalcemia", "Hypermagnesemia", "Hypoglycemia"]'::jsonb, 0, 'Ileostomy losses cause dehydration and hypokalemia.', 'PON 416 · General Surgery'),
(3, 32, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 416 · General Surgery', 'A T-tube left in the common bile duct after exploration should:', '["Be flushed hourly with tap water", "Be clamped from the first day after surgery", "Drain by gravity into a closed bag", "Be removed within 2 hours of surgery"]'::jsonb, 2, 'Record bile output; it falls as the duct heals.', 'PON 416 · General Surgery'),
(3, 33, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 416 · General Surgery', 'Mesenteric ischaemia classically presents with:', '["Chronic constipation with no pain at all", "Pain that is relieved by eating and returns at night", "Painless jaundice with a palpable gallbladder", "Severe pain out of proportion to the examination"]'::jsonb, 3, 'Risk factors: AF, vascular disease. Lactate may be raised.', 'PON 416 · General Surgery'),
(3, 34, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 416 · General Surgery', 'Preoperative preparation for thyroidectomy includes administering Lugol''s iodine to:', '["Decrease gland vascularity", "Induce euthyroid state", "Reduce laryngeal spasm", "Increase hormone release"]'::jsonb, 0, 'Lugol''s iodine reduces the blood supply and firms up the gland, making surgery safer.', 'PON 416 · General Surgery'),
(3, 35, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 416 · General Surgery', 'Post-thyroidectomy, a nurse observes hypotension and tachycardia. The most probable cause is:', '["Hypothyroidism", "Anxiety", "Hemorrhage", "Laryngospasm"]'::jsonb, 2, 'Ongoing bleeding causing hypovolaemia explains both hypotension and reflex tachycardia post-op.', 'PON 416 · General Surgery'),
(3, 36, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 416 · General Surgery', 'A patient develops tingling of fingers, muscle cramps, and carpopedal spasm after thyroidectomy. The nurse should suspect:', '["Hypercalcaemia", "Hypocalcaemia", "Hyponatremia", "Hyperkalemia"]'::jsonb, 1, 'Tingling, cramps, and carpopedal spasm are the classic early signs of hypocalcaemic tetany.', 'PON 416 · General Surgery'),
(3, 37, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 416 · General Surgery', 'The most common cause of large bowel obstruction. Select one:', '["Adhesions.", "Ischemia", "Inflammatory bowel disease.", "Tumor of the large bowel."]'::jsonb, 3, 'Tumours of the large bowel are the most common cause of large bowel obstruction in adults.', 'PON 416 · General Surgery'),
(3, 38, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 416 · General Surgery', 'The common bile duct is investigated and stones removed endoscopically by:', '["Cystoscopy", "Colonoscopy", "Bronchoscopy", "ERCP"]'::jsonb, 3, 'Post-ERCP pancreatitis is a known complication.', 'PON 416 · General Surgery'),
(3, 39, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 416 · General Surgery', 'A burst abdomen (dehiscence with evisceration) is first managed by:', '["Covering the bowel with sterile saline-soaked packs and calling the surgeon", "Leaving the bowel uncovered so it can dry, and pushing it back in", "Pushing the bowel back into the abdomen by hand", "Applying a dry gauze and waiting for the ward round"]'::jsonb, 0, 'Keep the patient calm, lying with knees bent, and nil by mouth.', 'PON 416 · General Surgery'),
(3, 40, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 416 · General Surgery', 'A volvulus of the caecum or sigmoid colon is:', '["A gallstone stuck in the bile duct", "Acute inflammation of the appendix", "A twist of the bowel on its mesentery", "A full-thickness tear in the bowel wall"]'::jsonb, 2, 'Sigmoid volvulus may be untwisted by flexible sigmoidoscopy.', 'PON 416 · General Surgery'),
(3, 41, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Compartment syndrome causing pain on passive stretch of the affected muscle is significant because it is:', '["Never associated with compartment syndrome", "A late, unreliable sign", "Only seen after the compartment has already been decompressed", "Often one of the earliest warning signs"]'::jsonb, 3, 'Pain that is disproportionate to the injury, especially when a muscle is passively stretched, is often the earliest clue that compartment pressure is dangerously high, before pulses are even lost.', 'PON 417 · Trauma & Orthopaedics'),
(3, 42, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'A pathological fracture occurs:', '["Only in the skull after a fall from a great height", "Only in young children with soft bones", "Through bone weakened by disease, with little trauma", "Only after major road traffic accidents"]'::jsonb, 2, 'Causes include tumours, osteoporosis and infection.', 'PON 417 · Trauma & Orthopaedics'),
(3, 43, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'A Colles'' fracture is often treated with:', '["Closed reduction and a plaster backslab", "A halo vest for the wrist", "Skeletal traction through the radius", "A hip spica cast and bed rest for 6 weeks"]'::jsonb, 0, 'Check fingers for swelling and circulation.', 'PON 417 · Trauma & Orthopaedics'),
(3, 44, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'A halo vest is used to:', '["Reduce ankle swelling after sprain", "Support a broken wrist in children", "Immobilise the cervical spine", "Treat a fractured femur in adults"]'::jsonb, 2, 'Keep the spanner for emergency removal attached to the vest.', 'PON 417 · Trauma & Orthopaedics'),
(3, 45, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Most long bone fractures in adults take about how long to unite?', '["About 2 weeks", "6–12 weeks", "About 1 year", "3–5 days"]'::jsonb, 1, 'Lower limb bones take longer than upper limb bones.', 'PON 417 · Trauma & Orthopaedics'),
(3, 46, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Weight-bearing exercise is encouraged in osteoporosis because it:', '["Weakens the bones further", "Helps maintain bone density", "Has no effect on the bones", "Causes fractures in most cases"]'::jsonb, 1, 'Combine with calcium, vitamin D and fall prevention.', 'PON 417 · Trauma & Orthopaedics'),
(3, 47, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'A patient after spinal fusion surgery should be mobilised by:', '["Lifting heavy objects to build strength", "Sitting up suddenly without any help", "Twisting and bending early to free the spine", "Log rolling and following the activity plan"]'::jsonb, 3, 'Avoid twisting and bending in the early weeks.', 'PON 417 · Trauma & Orthopaedics'),
(3, 48, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'A new plaster of Paris cast should be:', '["Pressed with the fingertips to shape it", "Handled with the palms until it is dry", "Dried quickly with a hot hair dryer", "Covered tightly with plastic immediately"]'::jsonb, 1, 'Fingertip dents create pressure points.', 'PON 417 · Trauma & Orthopaedics'),
(3, 49, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Developmental dysplasia of the hip (DDH) in babies is screened with:', '["Barlow and Ortolani tests, then ultrasound", "MRI of the spine and pelvis under general anaesthesia", "Chest X-ray at 6 weeks of age", "Blood tests for calcium and vitamin D"]'::jsonb, 0, 'Treatment includes a Pavlik harness.', 'PON 417 · Trauma & Orthopaedics'),
(3, 50, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'A patient with an open fracture is triaged as yellow. This means:', '["Expectant", "Minor injury", "Care can be delayed", "Immediate care needed"]'::jsonb, 2, 'Yellow (delayed) for serious but not immediately life-threatening injuries.', 'PON 417 · Trauma & Orthopaedics'),
(3, 51, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Which of the following is an orthopaedic-specific indication for ICU admission?', '["Fat embolism syndrome", "Isolated ankle sprain", "Minor wrist fracture", "Uncomplicated cast application"]'::jsonb, 0, 'Fat embolism is a systemic, potentially life-threatening complication of fracture, unlike the other minor orthopaedic issues listed.', 'PON 417 · Trauma & Orthopaedics'),
(3, 52, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Osteomyelitis in a child commonly affects the:', '["Metaphysis of long bones", "Fingernail beds", "Skull bones only", "Vertebrae only, in the lumbar spine"]'::jsonb, 0, 'Children present with fever and refusal to use the limb.', 'PON 417 · Trauma & Orthopaedics'),
(3, 53, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'A patient with a femur fracture is at risk for fat embolism syndrome. Signs include:', '["Hypertension and bradycardia", "Polyuria", "Hyperglycemia", "Hypoxia and petechiae"]'::jsonb, 3, 'Fat embolism causes respiratory distress (hypoxia) and petechiae.', 'PON 417 · Trauma & Orthopaedics'),
(3, 54, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Nutrition should ideally be started in a critically ill orthopaedic patient within:', '["24–48 hours", "2–4 hours", "1 week", "2 weeks"]'::jsonb, 0, 'Early nutrition (24–48 hours) helps counter the hypermetabolic, catabolic state of critical illness.', 'PON 417 · Trauma & Orthopaedics'),
(3, 55, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'A patient in a new plaster cast complains of a burning spot under the cast. The nurse suspects:', '["A cast that has become too loose", "Bone infection only, not skin", "Normal healing of the bone", "A pressure sore under the cast"]'::jsonb, 3, 'Report it; the cast may need a window or change.', 'PON 417 · Trauma & Orthopaedics'),
(3, 56, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'A pelvic binder in a patient with pelvic fracture should be placed around the:', '["Both knees", "Iliac crests", "Lower ribs, above the umbilicus", "Greater trochanters"]'::jsonb, 3, 'It closes the pelvic ring and reduces bleeding.', 'PON 417 · Trauma & Orthopaedics'),
(3, 57, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Lying prone for periods after above-knee amputation helps prevent:', '["Hip flexion contracture", "Wound infection", "Phantom limb pain", "Pressure ulcers on the stump"]'::jsonb, 0, 'Do not place pillows under the stump.', 'PON 417 · Trauma & Orthopaedics'),
(3, 58, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Hip fracture surgery in the elderly should ideally be performed within:', '["One month of the injury, once fit", "36 hours of admission", "2 weeks of admission", "6 months of injury"]'::jsonb, 1, 'Early surgery reduces complications and death.', 'PON 417 · Trauma & Orthopaedics'),
(3, 59, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'After an open reduction internal fixation (ORIF) of the ankle, the leg should be:', '["Elevated to reduce swelling", "Walked on fully on day 1 in all cases", "Wrapped tightly with an elastic bandage", "Kept hanging down"]'::jsonb, 0, 'Weight-bearing status depends on the surgeon''s instructions.', 'PON 417 · Trauma & Orthopaedics'),
(3, 60, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'The most important post-operative observation after limb surgery is:', '["Hair growth on the operated limb", "Nail colour only, checked once a day on the ward round", "Daily weight on the ward scales", "Regular neurovascular checks of the limb"]'::jsonb, 3, 'Report pain out of proportion, pallor, coldness or numbness.', 'PON 417 · Trauma & Orthopaedics'),
(3, 61, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'The 5 Ps of compartment syndrome are:', '["Pallor, Pyrexia, Paraesthesia, Pain, Pulselessness only", "Pain, Pallor, Paraesthesia, Pulselessness, Pain on passive stretch", "Pressure, Pulse, Pain, Paralysis, Puncture", "Pain, Pulse, Pallor, Puffiness, Pyrexia"]'::jsonb, 1, 'These are the classic warning signs of dangerously rising pressure inside a muscle compartment.', 'PON 417 · Trauma & Orthopaedics'),
(3, 62, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Rickets in children is caused mainly by:', '["Vitamin C deficiency", "Excess calcium", "Vitamin D deficiency", "Iron deficiency"]'::jsonb, 2, 'It causes bowed legs and soft bones.', 'PON 417 · Trauma & Orthopaedics'),
(3, 63, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'After a below-knee amputation, the stump is bandaged in a figure-of-eight pattern to:', '["Prevent all pain completely and permanently", "Shape the stump and reduce swelling", "Stop all blood supply to the stump", "Keep the knee joint bent at all times"]'::jsonb, 1, 'Avoid circular bandaging, which acts as a tourniquet.', 'PON 417 · Trauma & Orthopaedics'),
(3, 64, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Rhabdomyolysis is detected by a raised blood level of:', '["Troponin only", "Serum bilirubin", "Creatine kinase", "Serum amylase"]'::jsonb, 2, 'Dark urine due to myoglobin may also be seen.', 'PON 417 · Trauma & Orthopaedics'),
(3, 65, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'A tendon repair of the hand is protected after surgery with:', '["A splint and controlled exercises", "Full gripping exercises at once", "No splint and no restrictions, so the hand stays mobile", "Heavy lifting to strengthen it"]'::jsonb, 0, 'Early protected movement prevents adhesions.', 'PON 417 · Trauma & Orthopaedics'),
(3, 66, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Arthrodesis is:', '["Draining a joint", "Surgical fusion of a joint", "Looking inside a joint with a camera", "Replacement of a joint"]'::jsonb, 1, 'It relieves pain but removes movement.', 'PON 417 · Trauma & Orthopaedics'),
(3, 67, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'A dynamic hip screw (DHS) is used mainly for:', '["Depressed skull fractures in young adults", "Mid-shaft clavicle fractures", "Distal radius (wrist) fractures", "Extracapsular (intertrochanteric) hip fractures"]'::jsonb, 3, 'The femoral head blood supply is usually preserved in these.', 'PON 417 · Trauma & Orthopaedics'),
(3, 68, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'The nurse notices a patient with a femoral shaft fracture becoming confused, breathless and with petechiae on day 2. This is most likely:', '["Fat embolism syndrome", "Wound infection", "Normal response to analgesia", "Alcohol withdrawal only"]'::jsonb, 0, 'Give oxygen and call for urgent review.', 'PON 417 · Trauma & Orthopaedics'),
(3, 69, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Ligamentous injury of the knee from twisting (e.g. ACL tear) is diagnosed clinically using:', '["The Babinski test", "The Lachman test", "The Romberg test", "Murphy''s sign"]'::jsonb, 1, 'MRI confirms the diagnosis.', 'PON 417 · Trauma & Orthopaedics'),
(3, 70, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Spinal tuberculosis (Pott''s disease) commonly causes:', '["Joint hypermobility in the fingers and wrists of both hands", "Hand deformities only, with no back pain", "Hearing loss and ringing in the ears", "Back pain, kyphosis and possible paraplegia"]'::jsonb, 3, 'Treat with anti-TB drugs; surgery for cord compression.', 'PON 417 · Trauma & Orthopaedics'),
(3, 71, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'A ruptured ectopic pregnancy with shock needs:', '["Bed rest only, with serial hCG measurements every 48 hours", "Waiting for repeat hCG", "Resuscitation and immediate laparotomy or laparoscopy", "Methotrexate and discharge"]'::jsonb, 2, 'Cross-match blood and inform theatre urgently.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 72, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'After evacuation of a molar pregnancy, the woman is advised to:', '["Stop all contraception and try to conceive again straight away", "Have a hysterectomy in all cases", "Avoid pregnancy until hCG follow-up is complete", "Become pregnant immediately"]'::jsonb, 2, 'Rising hCG may mean gestational trophoblastic neoplasia.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 73, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'A third- or fourth-degree perineal tear should be repaired:', '["By the woman at home", "In theatre by an experienced doctor with good lighting and anaesthesia", "Never; it heals alone", "Only after 6 weeks, once the swelling and bruising have settled"]'::jsonb, 1, 'Give antibiotics and laxatives afterwards.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 74, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'ACE inhibitors are contraindicated in pregnancy-related hypertension mainly because they can cause:', '["No significant risk", "Maternal hair loss", "Improved placental blood flow", "Fetal renal toxicity"]'::jsonb, 3, 'These drugs can damage the developing fetal kidneys, making them unsafe throughout pregnancy.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 75, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'The tumour marker commonly used in ovarian cancer is:', '["AFP alone", "CEA alone", "CA-125", "PSA"]'::jsonb, 2, 'It is also raised in benign conditions such as endometriosis.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 76, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Laparoscopic salpingostomy for ectopic pregnancy differs from salpingectomy because it:', '["Removes the whole tube", "Removes the ovary on the same side as the ectopic", "Removes the pregnancy but keeps the tube", "Removes the uterus"]'::jsonb, 2, 'Follow-up hCG is needed to check for persistent trophoblast.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 77, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Women are at high risk of venous thromboembolism after caesarean section, so care includes:', '["Early mobilisation, hydration and thromboprophylaxis as assessed", "Restricting fluids and bed rest for the first week after surgery", "Strict bed rest for a week", "Avoiding all anticoagulants"]'::jsonb, 0, 'Pregnancy itself is a hypercoagulable state.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 78, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Before caesarean section under general anaesthesia, the patient is given an antacid such as sodium citrate to:', '["Raise blood sugar and give energy before the operation starts", "Reduce the acidity of stomach contents in case of aspiration", "Increase uterine contractions", "Prevent post-operative pain"]'::jsonb, 1, 'H₂ blockers or PPIs are also given.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 79, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Vacuum (ventouse) delivery is contraindicated in:', '["A preterm baby under about 34 weeks", "A fully dilated cervix", "Maternal exhaustion", "A term baby in occipito-anterior position"]'::jsonb, 0, 'Preterm babies are at greater risk of scalp and brain injury.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 80, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'A myomectomy is preferred to hysterectomy for fibroids when:', '["She has completed her family and is 55", "The woman wishes to keep her fertility", "She has cervical cancer", "The fibroids are cancerous"]'::jsonb, 1, 'Blood loss can be heavy; tourniquets or vasopressin may be used.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 81, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Asherman''s syndrome (intrauterine adhesions) may follow:', '["Vaginal delivery without tears", "Vigorous curettage of the uterus", "Caesarean section with a low transverse incision", "Breastfeeding"]'::jsonb, 1, 'It can cause scanty periods and infertility.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 82, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'A missed miscarriage means:', '["The pregnancy is outside the uterus", "The cervix opened with heavy bleeding", "The fetus has died but has not been passed", "All the products of conception have been passed completely"]'::jsonb, 2, 'Options include medical or surgical evacuation.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 83, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'A pregnant patient presents with severe, constant abdominal pain, a tense/rigid uterus, and dark vaginal bleeding. This presentation is most concerning for:', '["Placenta praevia", "Braxton Hicks contractions", "Placental abruption", "Normal labour onset"]'::jsonb, 2, 'Painful bleeding with uterine rigidity/tenderness is characteristic of placental abruption, an obstetric emergency threatening both mother and fetus.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 84, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'The best time to give prophylactic antibiotics for caesarean section is:', '["Before the skin incision", "After the baby is born only", "Only if a fever appears", "On the next day"]'::jsonb, 0, 'Giving before incision lowers maternal infection.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 85, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Which of the following describes a partial praevia?', '["Cervical opening is completely covered by the placenta", "Placenta extends just to the edge of the cervix", "Acute on Chronic praevia", "Cervical opening is partially covered by the placenta"]'::jsonb, 3, 'Partial praevia means the placenta partially (not completely) covers the cervical os.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 86, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'The most common site of endometriosis is the:', '["Ovaries and pelvic peritoneum", "Skin of the arms", "Brain", "Lungs and pleura, causing cough during periods"]'::jsonb, 0, 'It causes painful periods, pain on intercourse and infertility.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 87, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'A patient on magnesium sulfate after caesarean section for pre-eclampsia should have hourly:', '["Temperature only, as other observations are not affected", "Respiratory rate, reflexes and urine output checks", "Blood glucose only", "Weight measurements"]'::jsonb, 1, 'Magnesium is excreted by the kidneys.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 88, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'A molar pregnancy (hydatidiform mole) typically shows:', '["Low hCG and a normal fetus", "Very high hCG and a ''snowstorm'' pattern on ultrasound", "No hCG at all in the blood, with a normal-looking fetus", "A normal placenta"]'::jsonb, 1, 'Treatment is suction evacuation with hCG follow-up.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 89, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'During hysteroscopy with fluid distension, the nurse records fluid input and output because of the risk of:', '["Hypothermia only", "Hypertension only", "Fluid overload and hyponatraemia", "Hypoglycaemia from the glucose in the fluid"]'::jsonb, 2, 'Stop if the fluid deficit exceeds the safe limit.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 90, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'In management of bleeding due to placenta Previa, a woman can...', '["Have emergency C-section or admission for bed rest", "Be admitted to the female surgical word", "Be sent home", "Deliver the baby vaginally"]'::jsonb, 0, 'Placenta praevia bleeding is managed with emergency C-section or admission for bed rest depending on severity.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 91, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Wertheim''s (radical) hysterectomy is performed for:', '["Uterovaginal prolapse in older women", "Uterine fibroids", "Early cervical cancer", "Ovarian cysts"]'::jsonb, 2, 'It removes the uterus, parametrium, upper vagina and pelvic nodes.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 92, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'The commonest surgical procedure used to treat ruptured tubal pregnancy is', '["Salpingo-oophorectomy", "oophorectomy", "Salpingectomy", "Total hysterectomy"]'::jsonb, 2, 'Salpingectomy (removal of the affected tube) is the standard surgery for a ruptured tubal pregnancy.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 93, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'After caesarean section, the urinary catheter is usually removed:', '["After about 2 weeks, once the wound has fully healed", "Immediately on leaving theatre", "About 12 hours after surgery, once the woman is mobile", "Only when she is discharged"]'::jsonb, 2, 'Check that she passes urine adequately afterwards.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 94, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'A pregnant patient at 32 weeks presents with painless, bright red vaginal bleeding. This presentation is most concerning for:', '["Round ligament pain", "Normal spotting in pregnancy", "Placental abruption", "Placenta praevia"]'::jsonb, 3, 'Painless bright red bleeding in later pregnancy is classic for placenta praevia, whereas placental abruption typically presents with painful bleeding.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 95, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'The final surgical option for life-threatening postpartum haemorrhage when other measures fail is:', '["Hysterectomy", "Cervical cerclage", "Myomectomy", "Tubal ligation only"]'::jsonb, 0, 'Earlier steps include balloon tamponade, B-Lynch and vessel ligation.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 96, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Manual removal of the placenta is indicated when:', '["The mother has a headache", "The placenta is retained with bleeding or after the time limit", "The baby is breech", "The cord is long and the baby was born quickly"]'::jsonb, 1, 'It is done under anaesthesia with antibiotic cover.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 97, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'This describe the premature separation of a normally situated placenta occurring after the 28th week of pregnancy.', '["Placenta accrete", "Placenta circumventer", "Placenta praevia", "Abruption placentae"]'::jsonb, 3, 'Premature separation of a normally implanted placenta after 28 weeks is abruptio placentae.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 98, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Manual vacuum aspiration (MVA) is used for:', '["Removal of ovarian cysts", "Uterine evacuation in early incomplete miscarriage", "Repair of perineal tears", "Delivery of the baby at caesarean section"]'::jsonb, 1, 'It can be done under local anaesthesia.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 99, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Pelvic inflammatory disease complicated by a tubo-ovarian abscess not responding to antibiotics may need:', '["Cervical cerclage", "Oral iron only", "No treatment, as it always resolves on its own", "Surgical or radiological drainage"]'::jsonb, 3, 'Long-term effects include infertility and ectopic pregnancy.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 100, 'Perioperative Mock — Day 3 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Uterine prolapse where the cervix comes out through the vaginal opening is described as:', '["Third-degree prolapse (procidentia if complete)", "First-degree prolapse", "Cystocele only, with the bladder bulging into the vagina", "Normal finding after birth"]'::jsonb, 0, 'Treatments include pessaries or vaginal hysterectomy.', 'PON 421 · Obstetric & Gynaecological Surgery');
